-- Masks blocked words (whole words, case-insensitive, light leetspeak folding).
-- Returns the cleaned text. Extra words can be passed (per-class lists).
create or replace function public.ce_clean_text(p_text text, p_extra text[] default '{}')
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_out  text := p_text;
  v_word text;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if p_text is null then
    return null;
  end if;
  for v_word in
    select w.word from public.ce_blocked_words w
    union
    select lower(trim(x)) from unnest(coalesce(p_extra, '{}')) as x where char_length(trim(x)) >= 2
  loop
    -- build a pattern that tolerates common character swaps (a->@/4, i->1/!, o->0, e->3, s->$/5)
    v_out := regexp_replace(
      v_out,
      '(^|[^[:alnum:]])(' ||
        regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(
          regexp_replace(v_word, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g'),
          'a', '[a@4]', 'g'), 'i', '[i1!l]', 'g'), 'o', '[o0]', 'g'), 'e', '[e3]', 'g'), 's', '[s$5]', 'g')
      || ')(?=$|[^[:alnum:]])',
      '\1' || repeat('*', char_length(v_word)),
      'gi'
    );
  end loop;
  return v_out;
end;
$$;

create or replace function public.ce_has_blocked_word(p_text text, p_extra text[] default '{}')
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_text is not null and public.ce_clean_text(p_text, p_extra) is distinct from p_text;
$$;

-- ---------------------------------------------------------------------------
-- Items, packs (shop catalog)
-- ---------------------------------------------------------------------------
create table public.ce_items (
  id          text primary key check (id ~ '^[a-z0-9_]+$'),
  name        text not null,
  description text not null default '',
  slot        text not null check (slot in ('head','face','body','background','medal')),
  rarity      text not null check (rarity in ('common','uncommon','rare','epic','legendary','mythic')),
  price       integer check (price is null or price > 0),     -- direct-buy price; null = not sold directly
  sort        integer not null default 0
);
alter table public.ce_items enable row level security;
create policy "items are readable by everyone" on public.ce_items for select using (true);

create table public.ce_packs (
  id          text primary key check (id ~ '^[a-z0-9_]+$'),
  name        text not null,
  description text not null default '',
  price       integer not null check (price > 0),
  color       text not null default '#7b4dff',
  sort        integer not null default 0
);
alter table public.ce_packs enable row level security;
create policy "packs are readable by everyone" on public.ce_packs for select using (true);

create table public.ce_pack_items (
  pack_id text not null references public.ce_packs(id) on delete cascade,
  item_id text not null references public.ce_items(id) on delete cascade,
  weight  numeric not null check (weight > 0),
  primary key (pack_id, item_id)
);
alter table public.ce_pack_items enable row level security;
create policy "pack contents are readable by everyone" on public.ce_pack_items for select using (true);

-- ---------------------------------------------------------------------------
-- Profiles
-- ---------------------------------------------------------------------------
create table public.ce_profiles (
  id                  uuid primary key references auth.users(id) on delete cascade,
  role                text not null check (role in ('student','teacher')),
  display_name        text not null check (char_length(trim(display_name)) between 1 and 40),
  bio                 text not null default '' check (char_length(bio) <= 160),
  avatar_color        text not null default '#7b4dff' check (avatar_color ~ '^#[0-9a-fA-F]{6}$'),
  equipped_head       text references public.ce_items(id) on delete set null,
  equipped_face       text references public.ce_items(id) on delete set null,
  equipped_body       text references public.ce_items(id) on delete set null,
  equipped_background text references public.ce_items(id) on delete set null,
  equipped_medal      text references public.ce_items(id) on delete set null,
  coins               integer not null default 0 check (coins >= 0),
  coins_spent         integer not null default 0,
  xp                  integer not null default 0,
  games_played        integer not null default 0,
  games_won           integer not null default 0,
  questions_answered  integer not null default 0,
  questions_correct   integer not null default 0,
  assignments_done    integer not null default 0,
  daily_streak        integer not null default 0,
  last_daily_claim    date,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
alter table public.ce_profiles enable row level security;

-- Clients may only edit cosmetic columns; everything else goes through RPCs.
revoke insert, update, delete on public.ce_profiles from anon, authenticated;
grant update (display_name, bio, avatar_color, equipped_head, equipped_face, equipped_body,
              equipped_background, equipped_medal) on public.ce_profiles to authenticated;

create table public.ce_inventory (
  user_id           uuid not null references public.ce_profiles(id) on delete cascade,
  item_id           text not null references public.ce_items(id) on delete cascade,
  quantity          integer not null default 1 check (quantity >= 1),
  first_acquired_at timestamptz not null default now(),
  primary key (user_id, item_id)
);
alter table public.ce_inventory enable row level security;
revoke insert, update, delete on public.ce_inventory from anon, authenticated;
create policy "users read own inventory" on public.ce_inventory
  for select to authenticated using (user_id = (select auth.uid()));

create table public.ce_coin_ledger (
  id         bigint generated always as identity primary key,
  user_id    uuid not null references public.ce_profiles(id) on delete cascade,
  delta      integer not null,
  reason     text not null,
  ref_id     text,
  created_at timestamptz not null default now()
);
create index ce_coin_ledger_user_idx on public.ce_coin_ledger (user_id, created_at desc);
alter table public.ce_coin_ledger enable row level security;
revoke insert, update, delete on public.ce_coin_ledger from anon, authenticated;
create policy "users read own ledger" on public.ce_coin_ledger
  for select to authenticated using (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Economy helpers (internal; not callable by clients)
-- ---------------------------------------------------------------------------
create or replace function public.ce__add_coins(p_user uuid, p_delta integer, p_reason text, p_ref text default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare v_new integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if p_delta = 0 then
    select coins into v_new from public.ce_profiles where id = p_user;
    return v_new;
  end if;
  update public.ce_profiles
     set coins = coins + p_delta,
         coins_spent = coins_spent + greatest(-p_delta, 0),
         updated_at = now()
   where id = p_user
  returning coins into v_new;
  if v_new is null then
    raise exception 'profile not found';
  end if;
  insert into public.ce_coin_ledger (user_id, delta, reason, ref_id) values (p_user, p_delta, p_reason, p_ref);
  return v_new;
end;
$$;

-- Grants an item. Returns true if it was new to the user.
create or replace function public.ce__grant_item(p_user uuid, p_item text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare v_new boolean;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  insert into public.ce_inventory (user_id, item_id) values (p_user, p_item)
  on conflict (user_id, item_id) do update set quantity = public.ce_inventory.quantity + 1
  returning (xmax = 0) into v_new;
  return v_new;
end;
$$;

-- Grants a medal once (no duplicates). Returns true if newly earned.
create or replace function public.ce__grant_medal(p_user uuid, p_medal text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if exists (select 1 from public.ce_inventory where user_id = p_user and item_id = p_medal) then
    return false;
  end if;
  insert into public.ce_inventory (user_id, item_id) values (p_user, p_medal) on conflict do nothing;
  return found;
end;
$$;

revoke execute on function public.ce__add_coins(uuid, integer, text, text) from public, anon, authenticated;
revoke execute on function public.ce__grant_item(uuid, text) from public, anon, authenticated;
revoke execute on function public.ce__grant_medal(uuid, text) from public, anon, authenticated;

