-- (removed for Cinnabar: Cinnabar creates accounts; ce_enroll makes the Cesium profile)

-- Validate cosmetic profile edits: owned items, correct slots, clean names.
create or replace function public.ce_profiles_before_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_slot text;
  v_col  text;
  v_item text;
begin
  new.updated_at := now();
  new.display_name := trim(new.display_name);
  if public.ce_has_blocked_word(new.display_name) then
    raise exception 'That name contains a blocked word' using errcode = 'P0001';
  end if;
  if public.ce_has_blocked_word(new.bio) then
    raise exception 'That bio contains a blocked word' using errcode = 'P0001';
  end if;

  -- Only validate equipment when changed by a client (auth.uid() is set).
  if (select auth.uid()) is not null then
    foreach v_col in array array['head','face','body','background','medal'] loop
      v_item := case v_col
        when 'head' then new.equipped_head
        when 'face' then new.equipped_face
        when 'body' then new.equipped_body
        when 'background' then new.equipped_background
        else new.equipped_medal end;
      if v_item is not null then
        select slot into v_slot from public.ce_items where id = v_item;
        if v_slot is distinct from v_col then
          raise exception 'Item % cannot be equipped in the % slot', v_item, v_col using errcode = 'P0001';
        end if;
        if not exists (select 1 from public.ce_inventory where user_id = new.id and item_id = v_item) then
          raise exception 'You do not own that item' using errcode = 'P0001';
        end if;
      end if;
    end loop;
  end if;
  return new;
end;
$$;

create trigger profiles_before_update
  before update on public.ce_profiles
  for each row execute function public.ce_profiles_before_update();

-- ---------------------------------------------------------------------------
-- Shop RPCs
-- ---------------------------------------------------------------------------
create or replace function public.ce_rarity_refund(p_rarity text)
returns integer
language sql
immutable
as $$
  select case p_rarity
    when 'common' then 3 when 'uncommon' then 6 when 'rare' then 15
    when 'epic' then 35 when 'legendary' then 90 when 'mythic' then 250 else 0 end;
$$;

create or replace function public.ce_purchase_pack(p_pack_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := (select auth.uid());
  v_pack   public.ce_packs;
  v_coins  integer;
  v_total  numeric;
  v_roll   numeric;
  v_item   public.ce_items;
  v_new    boolean;
  v_refund integer := 0;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  select * into v_pack from public.ce_packs where id = p_pack_id;
  if not found then raise exception 'Pack not found' using errcode = 'P0002'; end if;

  select coins into v_coins from public.ce_profiles where id = v_uid for update;
  if v_coins is null then raise exception 'Profile not found'; end if;
  if v_coins < v_pack.price then
    raise exception 'Not enough coins' using errcode = 'P0001';
  end if;

  perform public.ce__add_coins(v_uid, -v_pack.price, 'pack', p_pack_id);

  select sum(weight) into v_total from public.ce_pack_items where pack_id = p_pack_id;
  v_roll := random() * v_total;
  select i.* into v_item
    from (
      select pi.item_id, sum(pi.weight) over (order by pi.item_id) as cum
        from public.ce_pack_items pi where pi.pack_id = p_pack_id
    ) c
    join public.ce_items i on i.id = c.item_id
   where c.cum >= v_roll
   order by c.cum
   limit 1;

  v_new := public.ce__grant_item(v_uid, v_item.id);
  if not v_new then
    v_refund := public.ce_rarity_refund(v_item.rarity);
    perform public.ce__add_coins(v_uid, v_refund, 'duplicate_refund', v_item.id);
  end if;

  if (select count(*) from public.ce_inventory where user_id = v_uid and item_id not like 'medal_%') >= 10 then
    perform public.ce__grant_medal(v_uid, 'medal_collector');
  end if;
  if (select coins_spent from public.ce_profiles where id = v_uid) >= 1000 then
    perform public.ce__grant_medal(v_uid, 'medal_big_spender');
  end if;

  return jsonb_build_object(
    'item_id', v_item.id, 'name', v_item.name, 'rarity', v_item.rarity, 'slot', v_item.slot,
    'is_new', v_new, 'refund', v_refund,
    'coins', (select coins from public.ce_profiles where id = v_uid));
end;
$$;

create or replace function public.ce_purchase_item(p_item_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid   uuid := (select auth.uid());
  v_item  public.ce_items;
  v_coins integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  select * into v_item from public.ce_items where id = p_item_id;
  if not found or v_item.price is null or v_item.slot = 'medal' then
    raise exception 'That item is not for sale' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.ce_inventory where user_id = v_uid and item_id = p_item_id) then
    raise exception 'You already own that item' using errcode = 'P0001';
  end if;
  select coins into v_coins from public.ce_profiles where id = v_uid for update;
  if v_coins < v_item.price then
    raise exception 'Not enough coins' using errcode = 'P0001';
  end if;
  perform public.ce__add_coins(v_uid, -v_item.price, 'item', p_item_id);
  perform public.ce__grant_item(v_uid, p_item_id);
  if (select coins_spent from public.ce_profiles where id = v_uid) >= 1000 then
    perform public.ce__grant_medal(v_uid, 'medal_big_spender');
  end if;
  return jsonb_build_object('item_id', v_item.id, 'coins', (select coins from public.ce_profiles where id = v_uid));
end;
$$;

-- Daily reward: 25 coins + 5 per streak day (max +50). Uses UTC days.
create or replace function public.ce_claim_daily_reward()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := (select auth.uid());
  v_prof   public.ce_profiles;
  v_today  date := (now() at time zone 'utc')::date;
  v_streak integer;
  v_amount integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  select * into v_prof from public.ce_profiles where id = v_uid for update;
  if v_prof.role <> 'student' then
    raise exception 'Only students earn coins' using errcode = 'P0001';
  end if;
  if v_prof.last_daily_claim = v_today then
    raise exception 'Already claimed today' using errcode = 'P0001';
  end if;
  v_streak := case when v_prof.last_daily_claim = v_today - 1 then v_prof.daily_streak + 1 else 1 end;
  v_amount := 25 + least(v_streak - 1, 10) * 5;
  update public.ce_profiles set last_daily_claim = v_today, daily_streak = v_streak where id = v_uid;
  perform public.ce__add_coins(v_uid, v_amount, 'daily_reward', v_today::text);
  if v_streak >= 7 then
    perform public.ce__grant_medal(v_uid, 'medal_streak');
  end if;
  return jsonb_build_object('amount', v_amount, 'streak', v_streak,
    'coins', (select coins from public.ce_profiles where id = v_uid));
end;
$$;

