-- ============================================================================
-- Cesium — classes, membership, grading structure
-- ============================================================================

create table public.ce_classes (
  id                uuid primary key default gen_random_uuid(),
  teacher_id        uuid not null references public.ce_profiles(id) on delete cascade,
  name              text not null check (char_length(trim(name)) between 1 and 60),
  period            text not null check (char_length(trim(period)) between 1 and 12),
  is_weighted       boolean not null default false,   -- AP / dual-credit
  color             text not null default '#6440c8' check (color ~ '^#[0-9a-fA-F]{6}$'),
  theme             text not null default 'atom',     -- thumbnail art preset
  code              text not null unique check (code ~ '^[A-Z2-9]{6}$'),
  chat_enabled      boolean not null default true,
  students_can_post boolean not null default false,
  banned_words      text[] not null default '{}',
  archived_at       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index ce_classes_teacher_idx on public.ce_classes (teacher_id);
alter table public.ce_classes enable row level security;

create table public.ce_class_members (
  class_id    uuid not null references public.ce_classes(id) on delete cascade,
  user_id     uuid not null references public.ce_profiles(id) on delete cascade,
  joined_at   timestamptz not null default now(),
  muted_until timestamptz,
  primary key (class_id, user_id)
);
create index ce_class_members_user_idx on public.ce_class_members (user_id);
alter table public.ce_class_members enable row level security;

create table public.ce_class_visits (
  user_id    uuid not null references public.ce_profiles(id) on delete cascade,
  class_id   uuid not null references public.ce_classes(id) on delete cascade,
  visited_at timestamptz not null default now(),
  primary key (user_id, class_id)
);
alter table public.ce_class_visits enable row level security;

create table public.ce_grading_periods (
  id        uuid primary key default gen_random_uuid(),
  class_id  uuid not null references public.ce_classes(id) on delete cascade,
  name      text not null check (char_length(trim(name)) between 1 and 30),
  starts_on date not null,
  ends_on   date not null,
  position  integer not null default 0,
  check (ends_on >= starts_on)
);
create index ce_grading_periods_class_idx on public.ce_grading_periods (class_id);
alter table public.ce_grading_periods enable row level security;

create table public.ce_grade_categories (
  id          uuid primary key default gen_random_uuid(),
  class_id    uuid not null references public.ce_classes(id) on delete cascade,
  name        text not null check (char_length(trim(name)) between 1 and 40),
  weight      numeric(5,2) not null default 0 check (weight >= 0 and weight <= 100),
  drop_lowest integer not null default 0 check (drop_lowest >= 0 and drop_lowest <= 10),
  position    integer not null default 0
);
create index ce_grade_categories_class_idx on public.ce_grade_categories (class_id);
alter table public.ce_grade_categories enable row level security;

-- ---------------------------------------------------------------------------
-- Access helpers (security definer to avoid RLS recursion)
-- ---------------------------------------------------------------------------
create or replace function public.ce_is_teacher()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ce_profiles where id = (select auth.uid()) and role = 'teacher');
$$;

create or replace function public.ce_is_class_teacher(p_class uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ce_classes where id = p_class and teacher_id = (select auth.uid()));
$$;

create or replace function public.ce_is_class_student(p_class uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ce_class_members where class_id = p_class and user_id = (select auth.uid()));
$$;

create or replace function public.ce_can_access_class(p_class uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select public.ce_is_class_teacher(p_class) or public.ce_is_class_student(p_class);
$$;

-- True if the current user and p_other are in at least one class together.
create or replace function public.ce_shares_class(p_other uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
      from public.ce_class_members a
      join public.ce_class_members b on b.class_id = a.class_id
     where a.user_id = (select auth.uid()) and b.user_id = p_other
  ) or exists (
    select 1 from public.ce_classes c join public.ce_class_members m on m.class_id = c.id
     where (c.teacher_id = (select auth.uid()) and m.user_id = p_other)
        or (c.teacher_id = p_other and m.user_id = (select auth.uid()))
  );
$$;

create or replace function public.ce_is_muted(p_class uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ce_class_members
                  where class_id = p_class and user_id = (select auth.uid())
                    and muted_until is not null and muted_until > now());
$$;

-- ---------------------------------------------------------------------------
-- Policies
-- ---------------------------------------------------------------------------
create policy "profiles: read self and classmates" on public.ce_profiles
  for select to authenticated
  using (id = (select auth.uid()) or public.ce_shares_class(id));
create policy "profiles: update self" on public.ce_profiles
  for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

create policy "classes: members read" on public.ce_classes
  for select to authenticated using (teacher_id = (select auth.uid()) or public.ce_is_class_student(id));
create policy "classes: teacher updates" on public.ce_classes
  for update to authenticated
  using (teacher_id = (select auth.uid())) with check (teacher_id = (select auth.uid()));
create policy "classes: teacher deletes" on public.ce_classes
  for delete to authenticated using (teacher_id = (select auth.uid()));
-- inserts happen through create_class()
revoke insert, update on public.ce_classes from anon, authenticated;
grant update (name, period, is_weighted, color, theme, chat_enabled, students_can_post,
              banned_words, archived_at) on public.ce_classes to authenticated;

create policy "class_members: read roster" on public.ce_class_members
  for select to authenticated using (public.ce_can_access_class(class_id));
create policy "class_members: teacher removes or student leaves" on public.ce_class_members
  for delete to authenticated
  using (public.ce_is_class_teacher(class_id) or user_id = (select auth.uid()));
create policy "class_members: teacher mutes" on public.ce_class_members
  for update to authenticated
  using (public.ce_is_class_teacher(class_id)) with check (public.ce_is_class_teacher(class_id));
revoke insert on public.ce_class_members from anon, authenticated;
revoke update on public.ce_class_members from authenticated;
grant update (muted_until) on public.ce_class_members to authenticated;

create policy "class_visits: own" on public.ce_class_visits
  for select to authenticated using (user_id = (select auth.uid()));
revoke insert, update, delete on public.ce_class_visits from anon, authenticated;

create policy "grading_periods: read" on public.ce_grading_periods
  for select to authenticated using (public.ce_can_access_class(class_id));
create policy "grading_periods: teacher writes" on public.ce_grading_periods
  for all to authenticated
  using (public.ce_is_class_teacher(class_id)) with check (public.ce_is_class_teacher(class_id));

create policy "grade_categories: read" on public.ce_grade_categories
  for select to authenticated using (public.ce_can_access_class(class_id));
create policy "grade_categories: teacher writes" on public.ce_grade_categories
  for all to authenticated
  using (public.ce_is_class_teacher(class_id)) with check (public.ce_is_class_teacher(class_id));

-- ---------------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------------
create or replace function public.ce_touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger classes_touch before update on public.ce_classes
  for each row execute function public.ce_touch_updated_at();

create or replace function public.ce_classes_validate()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  new.name := trim(new.name);
  new.period := trim(new.period);
  if public.ce_has_blocked_word(new.name) then
    raise exception 'Class name contains a blocked word' using errcode = 'P0001';
  end if;
  new.banned_words := coalesce(
    (select array_agg(distinct lower(trim(w))) from unnest(new.banned_words) w where char_length(trim(w)) between 2 and 40),
    '{}');
  return new;
end;
$$;
create trigger classes_validate before insert or update on public.ce_classes
  for each row execute function public.ce_classes_validate();

-- ---------------------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------------------
create or replace function public.ce_generate_class_code()
returns text language plpgsql volatile set search_path = '' as $$
declare
  v_alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_code text;
  i int;
begin
  loop
    v_code := '';
    for i in 1..6 loop
      v_code := v_code || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from public.ce_classes where code = v_code);
  end loop;
  return v_code;
end;
$$;

-- Picks the palette color least used by the teacher's existing classes.
create or replace function public.ce_pick_class_color(p_teacher uuid)
returns text language sql stable set search_path = '' as $$
  with palette(color, ord) as (
    values ('#6440c8',1),('#d65db1',2),('#2f9e8f',3),('#e07a2e',4),('#3b7dd8',5),
           ('#c8404f',6),('#8a5cf6',7),('#4c9a2a',8),('#b8860b',9),('#0f8fb3',10)
  )
  select p.color
    from palette p
    left join public.ce_classes c on c.teacher_id = p_teacher and lower(c.color) = p.color and c.archived_at is null
   group by p.color, p.ord
   order by count(c.id), p.ord
   limit 1;
$$;

create or replace function public.ce_create_class(p_name text, p_period text, p_weighted boolean default false)
returns public.ce_classes
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid   uuid := (select auth.uid());
  v_class public.ce_classes;
  v_year  int;
  v_start date;
  v_themes constant text[] := array['atom','flask','book','globe','calc','palette','music','dna','rocket','code'];
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  if not public.ce_is_teacher() then
    raise exception 'Only teachers can create classes' using errcode = '42501';
  end if;
  if (select count(*) from public.ce_classes where teacher_id = v_uid and archived_at is null) >= 30 then
    raise exception 'You can have at most 30 active classes' using errcode = 'P0001';
  end if;

  insert into public.ce_classes (teacher_id, name, period, is_weighted, code, color, theme)
  values (v_uid, p_name, p_period, coalesce(p_weighted, false), public.ce_generate_class_code(),
          public.ce_pick_class_color(v_uid),
          v_themes[1 + floor(random() * array_length(v_themes, 1))::int])
  returning * into v_class;

  -- Default Skyward-style categories
  insert into public.ce_grade_categories (class_id, name, weight, position) values
    (v_class.id, 'Daily Work', 30, 0),
    (v_class.id, 'Practice',   20, 1),
    (v_class.id, 'Quizzes',    20, 2),
    (v_class.id, 'Tests',      30, 3);

  -- Default grading periods: four quarters of the current school year (Aug–May)
  v_year := extract(year from now())::int - case when extract(month from now()) < 7 then 1 else 0 end;
  v_start := make_date(v_year, 8, 1);
  insert into public.ce_grading_periods (class_id, name, starts_on, ends_on, position) values
    (v_class.id, 'Q1', v_start,                          make_date(v_year, 10, 15), 0),
    (v_class.id, 'Q2', make_date(v_year, 10, 16),        make_date(v_year, 12, 31), 1),
    (v_class.id, 'Q3', make_date(v_year + 1, 1, 1),      make_date(v_year + 1, 3, 15), 2),
    (v_class.id, 'Q4', make_date(v_year + 1, 3, 16),     make_date(v_year + 1, 6, 30), 3);

  insert into public.ce_class_visits (user_id, class_id) values (v_uid, v_class.id);
  return v_class;
end;
$$;

create or replace function public.ce_join_class(p_code text)
returns public.ce_classes
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid   uuid := (select auth.uid());
  v_class public.ce_classes;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  if public.ce_is_teacher() then
    raise exception 'Teacher accounts cannot join classes as students' using errcode = 'P0001';
  end if;
  select * into v_class from public.ce_classes
   where code = upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'))
     and archived_at is null;
  if not found then
    raise exception 'No class found with that code' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.ce_class_members where class_id = v_class.id and user_id = v_uid) then
    raise exception 'You are already in this class' using errcode = 'P0001';
  end if;
  if (select count(*) from public.ce_class_members where class_id = v_class.id) >= 99 then
    raise exception 'This class is full' using errcode = 'P0001';
  end if;
  insert into public.ce_class_members (class_id, user_id) values (v_class.id, v_uid);
  insert into public.ce_class_visits (user_id, class_id) values (v_uid, v_class.id)
    on conflict (user_id, class_id) do update set visited_at = now();
  perform public.ce__grant_medal(v_uid, 'medal_welcome');
  return v_class;
end;
$$;

create or replace function public.ce_regenerate_class_code(p_class uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare v_code text;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_is_class_teacher(p_class) then
    raise exception 'Not your class' using errcode = '42501';
  end if;
  v_code := public.ce_generate_class_code();
  update public.ce_classes set code = v_code where id = p_class;
  return v_code;
end;
$$;

create or replace function public.ce_record_class_visit(p_class uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_can_access_class(p_class) then
    return;
  end if;
  insert into public.ce_class_visits (user_id, class_id) values ((select auth.uid()), p_class)
  on conflict (user_id, class_id) do update set visited_at = now();
end;
$$;

-- Teacher-only lookup of a student's email is intentionally NOT provided (privacy).

-- ===================== 20261011000300_learning.sql =====================
-- ============================================================================
-- Cesium — question sets, assignments, attempts, grades, teams, live sessions
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Question sets
-- ---------------------------------------------------------------------------
create table public.ce_question_sets (
  id             uuid primary key default gen_random_uuid(),
  owner_id       uuid not null references public.ce_profiles(id) on delete cascade,
  title          text not null check (char_length(trim(title)) between 1 and 80),
  description    text not null default '' check (char_length(description) <= 500),
  subject        text not null default '' check (char_length(subject) <= 40),
  color          text not null default '#6440c8' check (color ~ '^#[0-9a-fA-F]{6}$'),
  is_public      boolean not null default false,
  question_count integer not null default 0,
  source_set_id  uuid references public.ce_question_sets(id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index ce_question_sets_owner_idx on public.ce_question_sets (owner_id);
create index ce_question_sets_public_idx on public.ce_question_sets (is_public) where is_public;
alter table public.ce_question_sets enable row level security;
create trigger question_sets_touch before update on public.ce_question_sets
  for each row execute function public.ce_touch_updated_at();

create table public.ce_questions (
  id          uuid primary key default gen_random_uuid(),
  set_id      uuid not null references public.ce_question_sets(id) on delete cascade,
  position    integer not null default 0,
  kind        text not null check (kind in ('mc','tf','typed')),
  prompt      text not null check (char_length(trim(prompt)) between 1 and 500),
  image_url   text check (image_url is null or char_length(image_url) <= 1000),
  choices     text[] not null default '{}',
  time_limit  integer not null default 20 check (time_limit between 5 and 300),
  created_at  timestamptz not null default now(),
  check (
    (kind = 'mc' and array_length(choices, 1) between 2 and 6) or
    (kind = 'tf' and choices = array['True','False']) or
    (kind = 'typed' and coalesce(array_length(choices, 1), 0) = 0)
  )
);
create index ce_questions_set_idx on public.ce_questions (set_id, position);
alter table public.ce_questions enable row level security;

-- Answer keys live in their own table so students can never select them.
create table public.ce_question_keys (
  question_id      uuid primary key references public.ce_questions(id) on delete cascade,
  set_id           uuid not null references public.ce_question_sets(id) on delete cascade,
  correct_choices  integer[] not null default '{}',
  accepted_answers text[] not null default '{}',
  explanation      text not null default '' check (char_length(explanation) <= 500)
);
create index ce_question_keys_set_idx on public.ce_question_keys (set_id);
alter table public.ce_question_keys enable row level security;

create or replace function public.ce_question_keys_validate()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_q public.ce_questions;
begin
  select * into v_q from public.ce_questions where id = new.question_id;
  if not found then raise exception 'Question not found'; end if;
  new.set_id := v_q.set_id;
  if v_q.kind in ('mc','tf') then
    if coalesce(array_length(new.correct_choices, 1), 0) = 0 then
      raise exception 'Pick at least one correct answer' using errcode = 'P0001';
    end if;
    if exists (select 1 from unnest(new.correct_choices) c where c < 0 or c >= array_length(v_q.choices, 1)) then
      raise exception 'Correct answer index out of range' using errcode = 'P0001';
    end if;
    new.accepted_answers := '{}';
  else
    new.accepted_answers := coalesce(
      (select array_agg(distinct trim(a)) from unnest(new.accepted_answers) a where trim(a) <> ''), '{}');
    if coalesce(array_length(new.accepted_answers, 1), 0) = 0 then
      raise exception 'Typed questions need at least one accepted answer' using errcode = 'P0001';
    end if;
    new.correct_choices := '{}';
  end if;
  return new;
end;
$$;
create trigger question_keys_validate before insert or update on public.ce_question_keys
  for each row execute function public.ce_question_keys_validate();

create or replace function public.ce_refresh_set_question_count()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_set uuid := coalesce(new.set_id, old.set_id);
begin
  update public.ce_question_sets
     set question_count = (select count(*) from public.ce_questions where set_id = v_set),
         updated_at = now()
   where id = v_set;
  return null;
end;
$$;
create trigger questions_count after insert or delete on public.ce_questions
  for each row execute function public.ce_refresh_set_question_count();

-- ---------------------------------------------------------------------------
-- Assignments (classwork). Every assignment is a game.
-- ---------------------------------------------------------------------------
create table public.ce_assignments (
  id              uuid primary key default gen_random_uuid(),
  class_id        uuid not null references public.ce_classes(id) on delete cascade,
  created_by      uuid not null references public.ce_profiles(id) on delete cascade,
  set_id          uuid references public.ce_question_sets(id) on delete restrict,
  title           text not null check (char_length(trim(title)) between 1 and 100),
  instructions    text not null default '' check (char_length(instructions) <= 2000),
  play_type       text not null check (play_type in ('solo','team','live')),
  mode            text not null check (char_length(mode) between 1 and 32),
  category_id     uuid references public.ce_grade_categories(id) on delete set null,
  points_possible numeric(7,2) not null default 100 check (points_possible >= 0 and points_possible <= 10000),
  is_graded       boolean not null default true,
  open_at         timestamptz,
  due_at          timestamptz,
  max_attempts    integer check (max_attempts is null or max_attempts between 1 and 100),
  settings        jsonb not null default '{}'::jsonb,
  status          text not null default 'published' check (status in ('draft','published')),
  live_session_id uuid,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  check (due_at is null or open_at is null or due_at > open_at)
);
create index ce_assignments_class_idx on public.ce_assignments (class_id, due_at);
create index ce_assignments_set_idx on public.ce_assignments (set_id);
alter table public.ce_assignments enable row level security;
create trigger assignments_touch before update on public.ce_assignments
  for each row execute function public.ce_touch_updated_at();

create or replace function public.ce_is_assignment_open(a public.ce_assignments)
returns boolean language sql stable as $$
  select a.status = 'published' and (a.open_at is null or a.open_at <= now());
$$;

-- Can the current user read questions of this set?
create or replace function public.ce_can_view_set(p_set uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
      select 1 from public.ce_question_sets s
       where s.id = p_set
         and (s.owner_id = (select auth.uid()) or (s.is_public and public.ce_is_teacher()))
    )
    or exists (
      select 1 from public.ce_assignments a
        join public.ce_class_members m on m.class_id = a.class_id and m.user_id = (select auth.uid())
       where a.set_id = p_set and a.status = 'published' and a.play_type in ('solo','team')
         and (a.open_at is null or a.open_at <= now())
    )
    or exists (
      select 1 from public.ce_assignments a
        join public.ce_classes c on c.id = a.class_id and c.teacher_id = (select auth.uid())
       where a.set_id = p_set
    );
$$;

create or replace function public.ce_owns_set(p_set uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ce_question_sets where id = p_set and owner_id = (select auth.uid()));
$$;

create or replace function public.ce_can_view_set_keys(p_set uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.ce_question_sets s
     where s.id = p_set
       and (s.owner_id = (select auth.uid()) or (s.is_public and public.ce_is_teacher()))
  );
$$;

create policy "sets: read" on public.ce_question_sets
  for select to authenticated using (
    owner_id = (select auth.uid()) or (is_public and public.ce_is_teacher()) or public.ce_can_view_set(id));
create policy "sets: teacher inserts own" on public.ce_question_sets
  for insert to authenticated with check (owner_id = (select auth.uid()) and public.ce_is_teacher());
create policy "sets: owner updates" on public.ce_question_sets
  for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "sets: owner deletes" on public.ce_question_sets
  for delete to authenticated using (owner_id = (select auth.uid()));
revoke update on public.ce_question_sets from anon, authenticated;
grant update (title, description, subject, color, is_public) on public.ce_question_sets to authenticated;

create policy "questions: read" on public.ce_questions
  for select to authenticated using (public.ce_can_view_set(set_id));
create policy "questions: owner writes" on public.ce_questions
  for all to authenticated using (public.ce_owns_set(set_id)) with check (public.ce_owns_set(set_id));

create policy "keys: owner or teacher for public sets" on public.ce_question_keys
  for select to authenticated using (public.ce_can_view_set_keys(set_id));
create policy "keys: owner writes" on public.ce_question_keys
  for all to authenticated using (public.ce_owns_set(set_id)) with check (public.ce_owns_set(set_id));

create policy "assignments: class reads" on public.ce_assignments
  for select to authenticated using (
    public.ce_is_class_teacher(class_id) or (status = 'published' and public.ce_is_class_student(class_id)));
create policy "assignments: teacher inserts" on public.ce_assignments
  for insert to authenticated with check (
    public.ce_is_class_teacher(class_id) and created_by = (select auth.uid())
    and (set_id is null or public.ce_owns_set(set_id)));
create policy "assignments: teacher updates" on public.ce_assignments
  for update to authenticated
  using (public.ce_is_class_teacher(class_id))
  with check (public.ce_is_class_teacher(class_id) and (set_id is null or public.ce_owns_set(set_id)));
create policy "assignments: teacher deletes" on public.ce_assignments
  for delete to authenticated using (public.ce_is_class_teacher(class_id));

-- Copy any readable set into the caller's library (used before assigning someone else's public set)
create or replace function public.ce_copy_set(p_set uuid)
returns public.ce_question_sets
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_src public.ce_question_sets;
  v_new public.ce_question_sets;
  v_q   record;
  v_qid uuid;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_is_teacher() then raise exception 'Only teachers can copy sets' using errcode = '42501'; end if;
  select * into v_src from public.ce_question_sets where id = p_set;
  if not found or not public.ce_can_view_set_keys(p_set) then
    raise exception 'Set not found' using errcode = 'P0002';
  end if;
  insert into public.ce_question_sets (owner_id, title, description, subject, color, is_public, source_set_id)
  values ((select auth.uid()), left(v_src.title, 80), v_src.description, v_src.subject, v_src.color, false, v_src.id)
  returning * into v_new;
  for v_q in
    select q.*, k.correct_choices, k.accepted_answers, k.explanation
      from public.ce_questions q left join public.ce_question_keys k on k.question_id = q.id
     where q.set_id = p_set order by q.position
  loop
    insert into public.ce_questions (set_id, position, kind, prompt, image_url, choices, time_limit)
    values (v_new.id, v_q.position, v_q.kind, v_q.prompt, v_q.image_url, v_q.choices, v_q.time_limit)
    returning id into v_qid;
    insert into public.ce_question_keys (question_id, set_id, correct_choices, accepted_answers, explanation)
    values (v_qid, v_new.id, coalesce(v_q.correct_choices, '{}'), coalesce(v_q.accepted_answers, '{}'), coalesce(v_q.explanation, ''));
  end loop;
  select * into v_new from public.ce_question_sets where id = v_new.id;
  return v_new;
end;
$$;

-- Atomically replace all questions in a set (used by the set builder's Save).
-- p_questions: [{kind, prompt, image_url, choices[], time_limit, correct_choices[], accepted_answers[], explanation}]
create or replace function public.ce_save_set_questions(p_set uuid, p_questions jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_q   jsonb;
  v_pos integer := 0;
  v_qid uuid;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_owns_set(p_set) then raise exception 'Not your set' using errcode = '42501'; end if;
  if jsonb_typeof(p_questions) <> 'array' then raise exception 'Questions must be an array'; end if;
  if jsonb_array_length(p_questions) > 300 then
    raise exception 'A set can have at most 300 questions' using errcode = 'P0001';
  end if;
  delete from public.ce_questions where set_id = p_set;
  for v_q in select * from jsonb_array_elements(p_questions) loop
    insert into public.ce_questions (set_id, position, kind, prompt, image_url, choices, time_limit)
    values (
      p_set, v_pos, v_q->>'kind', trim(v_q->>'prompt'), nullif(trim(coalesce(v_q->>'image_url','')), ''),
      coalesce((select array_agg(trim(x)) from jsonb_array_elements_text(coalesce(v_q->'choices','[]'::jsonb)) x), '{}'),
      coalesce((v_q->>'time_limit')::int, 20))
    returning id into v_qid;
    insert into public.ce_question_keys (question_id, set_id, correct_choices, accepted_answers, explanation)
    values (
      v_qid, p_set,
      coalesce((select array_agg(x::int) from jsonb_array_elements_text(coalesce(v_q->'correct_choices','[]'::jsonb)) x), '{}'),
      coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(v_q->'accepted_answers','[]'::jsonb)) x), '{}'),
      left(coalesce(v_q->>'explanation', ''), 500));
    v_pos := v_pos + 1;
  end loop;
  update public.ce_question_sets set updated_at = now() where id = p_set;
  return v_pos;
end;
$$;

-- ---------------------------------------------------------------------------
-- Teams (Team Play)
-- ---------------------------------------------------------------------------
create table public.ce_teams (
  id            uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.ce_assignments(id) on delete cascade,
  name          text not null,
  color         text not null,
  position      integer not null default 0,
  score         bigint not null default 0
);
create index ce_teams_assignment_idx on public.ce_teams (assignment_id);
alter table public.ce_teams enable row level security;

