create or replace function public.ce_can_access_assignment(p_assignment uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ce_assignments a where a.id = p_assignment and public.ce_can_access_class(a.class_id));
$$;

create policy "teams: class reads" on public.ce_teams for select to authenticated
  using (public.ce_can_access_assignment(assignment_id));
create policy "team_members: class reads" on public.ce_team_members for select to authenticated
  using (public.ce_can_access_assignment(assignment_id));
create policy "team_tiles: class reads" on public.ce_team_tiles for select to authenticated
  using (public.ce_can_access_assignment(assignment_id));
create policy "team_events: class reads" on public.ce_team_events for select to authenticated
  using (public.ce_can_access_assignment(assignment_id));
revoke insert, update, delete on public.ce_teams, public.ce_team_members, public.ce_team_tiles, public.ce_team_events
  from anon, authenticated;

-- Creates balanced teams the first time, and places any not-yet-placed students on the smallest team.
create or replace function public.ce__ensure_teams(p_assignment uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_a       public.ce_assignments;
  v_count   integer;
  v_members integer;
  v_names   constant text[] := array['Proton','Neutron','Electron','Photon','Quark','Gluon','Muon','Boson'];
  v_colors  constant text[] := array['#7b4dff','#e0457b','#21a89a','#f08a24','#3b7dd8','#c8404f','#4c9a2a','#b8860b'];
  v_user    uuid;
  v_team    uuid;
  i         integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  select * into v_a from public.ce_assignments where id = p_assignment for update;
  if not found or v_a.play_type <> 'team' then return; end if;

  if not exists (select 1 from public.ce_teams where assignment_id = p_assignment) then
    select count(*) into v_members from public.ce_class_members where class_id = v_a.class_id;
    v_count := coalesce(nullif(v_a.settings->>'team_count', '')::int, 0);
    if v_count <= 0 then
      v_count := greatest(2, least(8, ceil(v_members / 4.0)::int));
    end if;
    v_count := greatest(2, least(8, v_count));
    for i in 1..v_count loop
      insert into public.ce_teams (assignment_id, name, color, position)
      values (p_assignment, 'Team ' || v_names[i], v_colors[i], i - 1);
    end loop;
  end if;

  -- Place every unplaced student (random order) on the currently smallest team.
  for v_user in
    select m.user_id from public.ce_class_members m
     where m.class_id = v_a.class_id
       and not exists (select 1 from public.ce_team_members tm where tm.assignment_id = p_assignment and tm.user_id = m.user_id)
     order by random()
  loop
    select t.id into v_team
      from public.ce_teams t
      left join public.ce_team_members tm on tm.team_id = t.id
     where t.assignment_id = p_assignment
     group by t.id, t.position
     order by count(tm.user_id), random()
     limit 1;
    insert into public.ce_team_members (assignment_id, team_id, user_id) values (p_assignment, v_team, v_user);
  end loop;
end;
$$;
revoke execute on function public.ce__ensure_teams(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Attempts (solo & team play) and answers
