  question_order uuid[] not null default '{}',
  answered_count integer not null default 0,   -- distinct questions answered
  correct_count  integer not null default 0,   -- distinct questions correct on first try
  total_answers  integer not null default 0,
  total_correct  integer not null default 0,
  credits        integer not null default 0,   -- team-mode action credits
  game_score     bigint not null default 0,
  percent        numeric(5,2),
  coins_awarded  integer not null default 0,
