create index ce_attempts_user_idx on public.ce_attempts (user_id, started_at desc);
create unique index ce_attempts_one_open_idx on public.ce_attempts (assignment_id, user_id) where status = 'in_progress';
alter table public.ce_attempts enable row level security;

create table public.ce_attempt_answers (
  id          bigint generated always as identity primary key,
  attempt_id  uuid not null references public.ce_attempts(id) on delete cascade,
  question_id uuid not null references public.ce_questions(id) on delete cascade,
