);
create index ce_attempt_answers_attempt_idx on public.ce_attempt_answers (attempt_id, question_id);
alter table public.ce_attempt_answers enable row level security;

create policy "attempts: own or class teacher" on public.ce_attempts for select to authenticated
  using (user_id = (select auth.uid()) or exists (
    select 1 from public.ce_assignments a where a.id = assignment_id and public.ce_is_class_teacher(a.class_id)));
create policy "attempt_answers: own or class teacher" on public.ce_attempt_answers for select to authenticated
  using (exists (
    select 1 from public.ce_attempts t join public.ce_assignments a on a.id = t.assignment_id
     where t.id = attempt_id and (t.user_id = (select auth.uid()) or public.ce_is_class_teacher(a.class_id))));
