create policy "grades: student reads own, teacher reads class" on public.ce_grades for select to authenticated
  using (student_id = (select auth.uid()) or exists (
    select 1 from public.ce_assignments a where a.id = assignment_id and public.ce_is_class_teacher(a.class_id)));
