create or replace function public.ce_grades_stamp()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  new.updated_at := now();
  if (select auth.uid()) is not null then
    new.updated_by := (select auth.uid());
  end if;
  return new;
end;
$$;
create trigger grades_stamp before insert or update on public.ce_grades
  for each row execute function public.ce_grades_stamp();

-- ---------------------------------------------------------------------------
-- Live sessions (host-run realtime games)
-- ---------------------------------------------------------------------------
create table public.ce_live_sessions (
  id            uuid primary key default gen_random_uuid(),
  class_id      uuid not null references public.ce_classes(id) on delete cascade,
  host_id       uuid not null references public.ce_profiles(id) on delete cascade,
  set_id        uuid references public.ce_question_sets(id) on delete set null,
  assignment_id uuid references public.ce_assignments(id) on delete set null,
  mode          text not null check (char_length(mode) between 1 and 32),
  title         text not null check (char_length(trim(title)) between 1 and 100),
  status        text not null default 'lobby' check (status in ('scheduled','lobby','running','ended','cancelled')),
  settings      jsonb not null default '{}'::jsonb,
  scheduled_for timestamptz,
  started_at    timestamptz,
  ended_at      timestamptz,
  created_at    timestamptz not null default now()
);
create index ce_live_sessions_class_idx on public.ce_live_sessions (class_id, status);
create unique index ce_live_sessions_one_active_idx on public.ce_live_sessions (class_id) where status in ('lobby','running');
alter table public.ce_live_sessions enable row level security;

alter table public.ce_assignments
  add constraint assignments_live_session_fk foreign key (live_session_id)
  references public.ce_live_sessions(id) on delete set null;

create table public.ce_live_results (
  session_id    uuid not null references public.ce_live_sessions(id) on delete cascade,
  user_id       uuid not null references public.ce_profiles(id) on delete cascade,
  rank          integer not null,
  score         bigint not null default 0,
  correct       integer not null default 0,
  answered      integer not null default 0,
  team          text,
  coins_awarded integer not null default 0,
  primary key (session_id, user_id)
);
alter table public.ce_live_results enable row level security;

create policy "live_sessions: class reads" on public.ce_live_sessions for select to authenticated
  using (public.ce_can_access_class(class_id));
create policy "live_sessions: host updates" on public.ce_live_sessions for update to authenticated
  using (host_id = (select auth.uid())) with check (host_id = (select auth.uid()));
create policy "live_sessions: host deletes unstarted" on public.ce_live_sessions for delete to authenticated
  using (host_id = (select auth.uid()) and status in ('scheduled','cancelled'));
revoke insert, update on public.ce_live_sessions from anon, authenticated;
grant update (status, title, settings, scheduled_for) on public.ce_live_sessions to authenticated;

create policy "live_results: class reads" on public.ce_live_results for select to authenticated
  using (exists (select 1 from public.ce_live_sessions s where s.id = session_id and public.ce_can_access_class(s.class_id)));
revoke insert, update, delete on public.ce_live_results from anon, authenticated;

-- Enforce legal status transitions and stamp timestamps.
create or replace function public.ce_live_sessions_transition()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.status is distinct from old.status then
    if not (
      (old.status = 'scheduled' and new.status in ('lobby','cancelled')) or
      (old.status = 'lobby'     and new.status in ('running','cancelled')) or
      (old.status = 'running'   and new.status in ('ended','cancelled'))
    ) then
      raise exception 'Cannot move a live game from % to %', old.status, new.status using errcode = 'P0001';
    end if;
    if new.status = 'running' then new.started_at := now(); end if;
    if new.status in ('ended','cancelled') then new.ended_at := now(); end if;
  end if;
  if old.status in ('ended','cancelled') then
    raise exception 'This live game is over' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger live_sessions_transition before update on public.ce_live_sessions
  for each row execute function public.ce_live_sessions_transition();

