-- ============================================================================
-- Cesium — stream, chat, reports, moderation
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Stream (class feed)
-- ---------------------------------------------------------------------------
create table public.ce_stream_posts (
  id              uuid primary key default gen_random_uuid(),
  class_id        uuid not null references public.ce_classes(id) on delete cascade,
  author_id       uuid references public.ce_profiles(id) on delete set null,
  kind            text not null default 'post' check (kind in ('post','assignment','live','system')),
  body            text not null check (char_length(trim(body)) between 1 and 2000),
  assignment_id   uuid references public.ce_assignments(id) on delete cascade,
  live_session_id uuid references public.ce_live_sessions(id) on delete cascade,
  pinned          boolean not null default false,
  created_at      timestamptz not null default now(),
  edited_at       timestamptz
);
create index ce_stream_posts_class_idx on public.ce_stream_posts (class_id, pinned desc, created_at desc);
alter table public.ce_stream_posts enable row level security;

create table public.ce_stream_replies (
  id         uuid primary key default gen_random_uuid(),
  post_id    uuid not null references public.ce_stream_posts(id) on delete cascade,
  class_id   uuid not null references public.ce_classes(id) on delete cascade,
  author_id  uuid not null references public.ce_profiles(id) on delete cascade,
  body       text not null check (char_length(trim(body)) between 1 and 1000),
  created_at timestamptz not null default now()
);
create index ce_stream_replies_post_idx on public.ce_stream_replies (post_id, created_at);
alter table public.ce_stream_replies enable row level security;

create table public.ce_stream_likes (
  post_id    uuid not null references public.ce_stream_posts(id) on delete cascade,
  user_id    uuid not null references public.ce_profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (post_id, user_id)
);
alter table public.ce_stream_likes enable row level security;

create policy "stream_posts: class reads" on public.ce_stream_posts for select to authenticated
  using (public.ce_can_access_class(class_id));
create policy "stream_posts: teacher or allowed student posts" on public.ce_stream_posts for insert to authenticated
  with check (
    author_id = (select auth.uid()) and kind = 'post' and assignment_id is null and live_session_id is null
    and (public.ce_is_class_teacher(class_id) or (
      public.ce_is_class_student(class_id) and not public.ce_is_muted(class_id)
      and exists (select 1 from public.ce_classes c where c.id = class_id and c.students_can_post)
      and pinned = false)));
create policy "stream_posts: author or teacher edits" on public.ce_stream_posts for update to authenticated
  using (author_id = (select auth.uid()) or public.ce_is_class_teacher(class_id))
  with check (public.ce_can_access_class(class_id));
create policy "stream_posts: author or teacher deletes" on public.ce_stream_posts for delete to authenticated
  using (author_id = (select auth.uid()) or public.ce_is_class_teacher(class_id));
revoke update on public.ce_stream_posts from anon, authenticated;
grant update (body, pinned) on public.ce_stream_posts to authenticated;

create policy "stream_replies: class reads" on public.ce_stream_replies for select to authenticated
  using (public.ce_can_access_class(class_id));
create policy "stream_replies: members reply" on public.ce_stream_replies for insert to authenticated
  with check (author_id = (select auth.uid()) and public.ce_can_access_class(class_id) and not public.ce_is_muted(class_id));
create policy "stream_replies: author or teacher deletes" on public.ce_stream_replies for delete to authenticated
  using (author_id = (select auth.uid()) or public.ce_is_class_teacher(class_id));
revoke update on public.ce_stream_replies from anon, authenticated;

create policy "stream_likes: class reads" on public.ce_stream_likes for select to authenticated
  using (exists (select 1 from public.ce_stream_posts p where p.id = post_id and public.ce_can_access_class(p.class_id)));
create policy "stream_likes: like as self" on public.ce_stream_likes for insert to authenticated
  with check (user_id = (select auth.uid())
              and exists (select 1 from public.ce_stream_posts p where p.id = post_id and public.ce_can_access_class(p.class_id)));
create policy "stream_likes: unlike own" on public.ce_stream_likes for delete to authenticated
  using (user_id = (select auth.uid()));

create or replace function public.ce_stream_before_write()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_extra text[];
begin
  select banned_words into v_extra from public.ce_classes where id = new.class_id;
  new.body := trim(public.ce_clean_text(new.body, v_extra));
  if tg_table_name = 'stream_posts' and tg_op = 'UPDATE' and new.body is distinct from old.body then
    new.edited_at := now();
  end if;
  -- Pinning is teacher-only
  if tg_table_name = 'stream_posts' and tg_op = 'UPDATE' and new.pinned is distinct from old.pinned
     and not public.ce_is_class_teacher(new.class_id) and (select auth.uid()) is not null then
    raise exception 'Only the teacher can pin posts' using errcode = '42501';
  end if;
  -- Only authors may edit text
  if tg_table_name = 'stream_posts' and tg_op = 'UPDATE' and new.body is distinct from old.body
     and old.author_id is distinct from (select auth.uid()) and (select auth.uid()) is not null then
    raise exception 'Only the author can edit a post' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger stream_posts_before_write before insert or update on public.ce_stream_posts
  for each row execute function public.ce_stream_before_write();

create or replace function public.ce_stream_replies_before_insert()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_extra text[]; v_class uuid;
begin
  select class_id into v_class from public.ce_stream_posts where id = new.post_id;
  if v_class is null then raise exception 'Post not found' using errcode = 'P0002'; end if;
  new.class_id := v_class;
  select banned_words into v_extra from public.ce_classes where id = v_class;
  new.body := trim(public.ce_clean_text(new.body, v_extra));
  if (select count(*) from public.ce_stream_replies
       where author_id = new.author_id and created_at > now() - interval '30 seconds') >= 5 then
    raise exception 'Slow down! Try again in a few seconds.' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger stream_replies_before_insert before insert on public.ce_stream_replies
  for each row execute function public.ce_stream_replies_before_insert();

-- ---------------------------------------------------------------------------
-- Chat (one room per class)
-- ---------------------------------------------------------------------------
create table public.ce_chat_messages (
  id          uuid primary key default gen_random_uuid(),
  class_id    uuid not null references public.ce_classes(id) on delete cascade,
  author_id   uuid not null references public.ce_profiles(id) on delete cascade,
  body        text not null check (char_length(trim(body)) between 1 and 500),
  was_filtered boolean not null default false,
  deleted_at  timestamptz,
  deleted_by  uuid references public.ce_profiles(id) on delete set null,
  created_at  timestamptz not null default now()
);
create index ce_chat_messages_class_idx on public.ce_chat_messages (class_id, created_at desc);
alter table public.ce_chat_messages enable row level security;

create policy "chat: class reads" on public.ce_chat_messages for select to authenticated
  using (public.ce_can_access_class(class_id));
create policy "chat: members send" on public.ce_chat_messages for insert to authenticated
  with check (
    author_id = (select auth.uid())
    and (public.ce_is_class_teacher(class_id) or (
      public.ce_is_class_student(class_id) and not public.ce_is_muted(class_id)
      and exists (select 1 from public.ce_classes c where c.id = class_id and c.chat_enabled))));
create policy "chat: teacher removes, author unsends" on public.ce_chat_messages for update to authenticated
  using (public.ce_is_class_teacher(class_id) or author_id = (select auth.uid()))
  with check (public.ce_is_class_teacher(class_id) or author_id = (select auth.uid()));
revoke update, delete on public.ce_chat_messages from anon, authenticated;
grant update (deleted_at) on public.ce_chat_messages to authenticated;

create or replace function public.ce_chat_before_write()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_extra text[]; v_clean text;
begin
  if tg_op = 'INSERT' then
    select banned_words into v_extra from public.ce_classes where id = new.class_id;
    v_clean := trim(public.ce_clean_text(new.body, v_extra));
    new.was_filtered := v_clean is distinct from trim(new.body);
    new.body := v_clean;
    new.deleted_at := null;
    new.deleted_by := null;
    new.created_at := now();
    if (select count(*) from public.ce_chat_messages
         where author_id = new.author_id and class_id = new.class_id
           and created_at > now() - interval '10 seconds') >= 5 then
      raise exception 'You''re sending messages too fast. Wait a few seconds.' using errcode = 'P0001';
    end if;
  else
    if old.deleted_at is not null then
      raise exception 'Message already removed' using errcode = 'P0001';
    end if;
    if new.deleted_at is not null then
      new.deleted_at := now();
      new.deleted_by := (select auth.uid());
    end if;
  end if;
  return new;
end;
$$;
create trigger chat_before_write before insert or update on public.ce_chat_messages
  for each row execute function public.ce_chat_before_write();

-- Students only see the body of non-deleted messages; deleted bodies are blanked for everyone.
create or replace function public.ce_chat_blank_deleted()
returns trigger language plpgsql as $$
begin
  if new.deleted_at is not null then
    new.body := '[removed]';
  end if;
  return new;
end;
$$;
create trigger chat_blank_deleted before update on public.ce_chat_messages
  for each row when (new.deleted_at is not null) execute function public.ce_chat_blank_deleted();

-- ---------------------------------------------------------------------------
-- Reports & moderation log
-- ---------------------------------------------------------------------------
create table public.ce_reports (
  id          uuid primary key default gen_random_uuid(),
  class_id    uuid not null references public.ce_classes(id) on delete cascade,
  reporter_id uuid not null references public.ce_profiles(id) on delete cascade,
  target_kind text not null check (target_kind in ('chat','post','reply','user')),
  target_id   text not null,
  target_user uuid references public.ce_profiles(id) on delete cascade,
  excerpt     text not null default '',
  reason      text not null check (char_length(trim(reason)) between 1 and 300),
  status      text not null default 'open' check (status in ('open','resolved','dismissed')),
  resolved_by uuid references public.ce_profiles(id) on delete set null,
  created_at  timestamptz not null default now(),
  resolved_at timestamptz
);
create index ce_reports_class_idx on public.ce_reports (class_id, status, created_at desc);
alter table public.ce_reports enable row level security;

create policy "reports: teacher reads class, reporter reads own" on public.ce_reports for select to authenticated
  using (public.ce_is_class_teacher(class_id) or reporter_id = (select auth.uid()));
create policy "reports: members file" on public.ce_reports for insert to authenticated
  with check (reporter_id = (select auth.uid()) and public.ce_can_access_class(class_id) and status = 'open');
create policy "reports: teacher resolves" on public.ce_reports for update to authenticated
  using (public.ce_is_class_teacher(class_id)) with check (public.ce_is_class_teacher(class_id));
revoke update on public.ce_reports from anon, authenticated;
grant update (status) on public.ce_reports to authenticated;

create or replace function public.ce_reports_before_write()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.reason := left(trim(new.reason), 300);
    -- Fill excerpt + target_user server-side so they can't be spoofed
    if new.target_kind = 'chat' then
      select left(body, 300), author_id into new.excerpt, new.target_user
        from public.ce_chat_messages where id::text = new.target_id and class_id = new.class_id;
    elsif new.target_kind = 'post' then
      select left(body, 300), author_id into new.excerpt, new.target_user
        from public.ce_stream_posts where id::text = new.target_id and class_id = new.class_id;
    elsif new.target_kind = 'reply' then
      select left(body, 300), author_id into new.excerpt, new.target_user
        from public.ce_stream_replies where id::text = new.target_id and class_id = new.class_id;
    else
      select display_name, id into new.excerpt, new.target_user
        from public.ce_profiles where id::text = new.target_id;
      if not public.ce_shares_class(new.target_user) then
        new.target_user := null;
      end if;
    end if;
    if new.target_user is null then
      raise exception 'Nothing to report there' using errcode = 'P0002';
    end if;
    if (select count(*) from public.ce_reports where reporter_id = new.reporter_id
         and created_at > now() - interval '1 hour') >= 20 then
      raise exception 'Too many reports. Try again later.' using errcode = 'P0001';
    end if;
  else
    if new.status is distinct from old.status and new.status <> 'open' then
      new.resolved_at := now();
      new.resolved_by := (select auth.uid());
    end if;
  end if;
  return new;
end;
$$;
create trigger reports_before_write before insert or update on public.ce_reports
  for each row execute function public.ce_reports_before_write();

create table public.ce_moderation_log (
  id           bigint generated always as identity primary key,
  class_id     uuid not null references public.ce_classes(id) on delete cascade,
  moderator_id uuid references public.ce_profiles(id) on delete set null,
  target_user  uuid references public.ce_profiles(id) on delete set null,
  action       text not null,
  details      text not null default '',
  created_at   timestamptz not null default now()
);
create index ce_moderation_log_class_idx on public.ce_moderation_log (class_id, created_at desc);
alter table public.ce_moderation_log enable row level security;
create policy "moderation_log: teacher reads" on public.ce_moderation_log for select to authenticated
  using (public.ce_is_class_teacher(class_id));
revoke insert, update, delete on public.ce_moderation_log from anon, authenticated;

-- Mute (minutes > 0) or unmute (minutes = 0) a student in a class.
create or replace function public.ce_set_mute(p_class uuid, p_user uuid, p_minutes integer)
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare v_until timestamptz;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_is_class_teacher(p_class) then raise exception 'Not your class' using errcode = '42501'; end if;
  if p_minutes < 0 or p_minutes > 525600 then raise exception 'Invalid duration' using errcode = 'P0001'; end if;
  v_until := case when p_minutes = 0 then null else now() + make_interval(mins => p_minutes) end;
  update public.ce_class_members set muted_until = v_until where class_id = p_class and user_id = p_user;
  if not found then raise exception 'Student not in class' using errcode = 'P0002'; end if;
  insert into public.ce_moderation_log (class_id, moderator_id, target_user, action, details)
  values (p_class, (select auth.uid()), p_user, case when p_minutes = 0 then 'unmute' else 'mute' end,
          case when p_minutes = 0 then '' else p_minutes || ' minutes' end);
  return v_until;
end;
$$;

create or replace function public.ce_remove_student(p_class uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_is_class_teacher(p_class) then raise exception 'Not your class' using errcode = '42501'; end if;
  delete from public.ce_class_members where class_id = p_class and user_id = p_user;
  if not found then raise exception 'Student not in class' using errcode = 'P0002'; end if;
  insert into public.ce_moderation_log (class_id, moderator_id, target_user, action)
  values (p_class, (select auth.uid()), p_user, 'remove');
end;
$$;

-- Log chat removals made by teachers.
create or replace function public.ce_chat_after_delete_log()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.deleted_at is not null and old.deleted_at is null and new.deleted_by is distinct from old.author_id then
    insert into public.ce_moderation_log (class_id, moderator_id, target_user, action, details)
    values (new.class_id, new.deleted_by, old.author_id, 'delete_message', left(old.body, 200));
  end if;
  return null;
end;
$$;
create trigger chat_after_delete_log after update on public.ce_chat_messages
  for each row execute function public.ce_chat_after_delete_log();

-- ===================== 20261011000500_gameplay.sql =====================
-- ============================================================================
-- Cesium — gameplay RPCs: attempts, answer checking, team actions, live games
-- ============================================================================

revoke update on public.ce_assignments from anon, authenticated;
grant update (title, instructions, category_id, points_possible, is_graded, open_at, due_at,
              max_attempts, settings, status, set_id) on public.ce_assignments to authenticated;

create or replace function public.ce_valid_mode(p_play_type text, p_mode text)
returns boolean language sql immutable as $$
  select case p_play_type
    when 'solo' then p_mode in ('classic','vault','nitro','tycoon','speedrun')
    when 'team' then p_mode in ('classic','nitro_relay','territory','team_vault')
    when 'live' then p_mode in ('stock_rush','head2head','vault','nitro','tug_of_war','tycoon','territory')
    else false end;
$$;

create or replace function public.ce_assignments_before_write()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  new.title := trim(new.title);
  if not public.ce_valid_mode(new.play_type, new.mode) then
    raise exception 'Mode % is not available for % play', new.mode, new.play_type using errcode = 'P0001';
  end if;
  if new.category_id is not null and not exists (
       select 1 from public.ce_grade_categories where id = new.category_id and class_id = new.class_id) then
    raise exception 'Category does not belong to this class' using errcode = 'P0001';
  end if;
  if new.play_type in ('solo','team') and new.status = 'published' then
    if new.set_id is null then
      raise exception 'Pick a question set first' using errcode = 'P0001';
    end if;
    if (select question_count from public.ce_question_sets where id = new.set_id) < 1 then
      raise exception 'That set has no questions yet' using errcode = 'P0001';
    end if;
  end if;
  if tg_op = 'UPDATE' and new.set_id is distinct from old.set_id
     and exists (select 1 from public.ce_attempts where assignment_id = new.id) then
    raise exception 'Students have already started this assignment; its set can''t be changed' using errcode = 'P0001';
  end if;
  if new.settings is null or jsonb_typeof(new.settings) <> 'object' then
    new.settings := '{}'::jsonb;
  end if;
  return new;
end;
$$;
create trigger assignments_before_write before insert or update on public.ce_assignments
  for each row execute function public.ce_assignments_before_write();

create or replace function public.ce_assignments_after_write()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_name text;
begin
  if new.status = 'published' and (tg_op = 'INSERT' or old.status <> 'published') and new.play_type in ('solo','team') then
    select display_name into v_name from public.ce_profiles where id = new.created_by;
    insert into public.ce_stream_posts (class_id, author_id, kind, body, assignment_id)
    values (new.class_id, new.created_by, 'assignment',
            coalesce(v_name, 'Your teacher') || ' added a new assignment called "' || new.title || '"', new.id);
    if new.play_type = 'team' then
      perform public.ce__ensure_teams(new.id);
    end if;
  end if;
  return null;
end;
$$;
create trigger assignments_after_write after insert or update on public.ce_assignments
  for each row execute function public.ce_assignments_after_write();

-- ---------------------------------------------------------------------------
-- Answer checking
-- ---------------------------------------------------------------------------
create or replace function public.ce_normalize_answer(p text)
returns text language sql immutable as $$
  select regexp_replace(regexp_replace(lower(trim(coalesce(p, ''))), '\s+', ' ', 'g'), '^[[:punct:] ]+|[[:punct:] ]+$', '', 'g');
$$;

-- Returns (is_correct, key). p_response: {"choice": int} for mc/tf, {"text": str} for typed.
create or replace function public.ce__check_answer(p_question uuid, p_response jsonb)
returns table (is_correct boolean, correct_choices integer[], accepted_answers text[], explanation text)
language plpgsql stable security definer set search_path = '' as $$
declare
  v_q public.ce_questions;
  v_k public.ce_question_keys;
  v_choice integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  select * into v_q from public.ce_questions where id = p_question;
  select * into v_k from public.ce_question_keys where question_id = p_question;
  if v_q.id is null or v_k.question_id is null then
    raise exception 'Question not found' using errcode = 'P0002';
  end if;
  if v_q.kind in ('mc','tf') then
    begin
      v_choice := (p_response->>'choice')::int;
    exception when others then
      v_choice := null;
    end;
    is_correct := v_choice is not null and v_choice = any(v_k.correct_choices);
  else
    is_correct := exists (
      select 1 from unnest(v_k.accepted_answers) a
       where public.ce_normalize_answer(a) = public.ce_normalize_answer(p_response->>'text')
         and public.ce_normalize_answer(a) <> '');
  end if;
  correct_choices := v_k.correct_choices;
  accepted_answers := v_k.accepted_answers;
  explanation := v_k.explanation;
  return next;
end;
$$;
revoke execute on function public.ce__check_answer(uuid, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Attempts
-- ---------------------------------------------------------------------------
create or replace function public.ce_start_attempt(p_assignment uuid)
returns public.ce_attempts
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := (select auth.uid());
  v_a       public.ce_assignments;
  v_attempt public.ce_attempts;
  v_limit   integer;
  v_order   uuid[];
  v_team    uuid;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  select * into v_a from public.ce_assignments where id = p_assignment;
  if not found or v_a.status <> 'published' or v_a.play_type not in ('solo','team') then
    raise exception 'Assignment not found' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.ce_class_members where class_id = v_a.class_id and user_id = v_uid) then
    raise exception 'You are not in this class' using errcode = '42501';
  end if;
  if v_a.open_at is not null and v_a.open_at > now() then
    raise exception 'This assignment is not open yet' using errcode = 'P0001';
  end if;

  select * into v_attempt from public.ce_attempts
   where assignment_id = p_assignment and user_id = v_uid and status = 'in_progress';
  if found then
    return v_attempt;
  end if;

  if v_a.due_at is not null and v_a.due_at < now()
     and coalesce((v_a.settings->>'allow_late')::boolean, true) = false then
    raise exception 'This assignment is closed' using errcode = 'P0001';
  end if;
  if v_a.max_attempts is not null and (
       select count(*) from public.ce_attempts
        where assignment_id = p_assignment and user_id = v_uid and status = 'submitted') >= v_a.max_attempts then
    raise exception 'No attempts left' using errcode = 'P0001';
  end if;

  v_limit := nullif(v_a.settings->>'question_limit', '')::int;
  select array_agg(id) into v_order from (
    select q.id from public.ce_questions q
     where q.set_id = v_a.set_id
     order by case when coalesce((v_a.settings->>'shuffle')::boolean, true) then random() else q.position end
     limit coalesce(v_limit, 1000)
  ) s;
  if v_order is null then
    raise exception 'This assignment has no questions' using errcode = 'P0001';
  end if;

  if v_a.play_type = 'team' then
    perform public.ce__ensure_teams(p_assignment);
    select team_id into v_team from public.ce_team_members where assignment_id = p_assignment and user_id = v_uid;
  end if;

  insert into public.ce_attempts (assignment_id, user_id, team_id, question_order)
  values (p_assignment, v_uid, v_team, v_order)
  returning * into v_attempt;
  return v_attempt;
end;
$$;

create or replace function public.ce_answer_question(p_attempt uuid, p_question uuid, p_response jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := (select auth.uid());
  v_t       public.ce_attempts;
  v_a       public.ce_assignments;
  v_check   record;
  v_first   boolean;
  v_reveal  boolean;
  v_gain    bigint := 0;
  v_score   bigint;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  select * into v_t from public.ce_attempts where id = p_attempt for update;
  if not found or v_t.user_id <> v_uid then raise exception 'Attempt not found' using errcode = 'P0002'; end if;
  if v_t.status <> 'in_progress' then raise exception 'This attempt is already submitted' using errcode = 'P0001'; end if;
  if not (p_question = any(v_t.question_order)) then
    raise exception 'That question is not part of this attempt' using errcode = 'P0001';
  end if;
  if v_t.last_answer_at is not null and v_t.last_answer_at > now() - interval '300 milliseconds' then
    raise exception 'Too fast' using errcode = 'P0001';
  end if;
  select * into v_a from public.ce_assignments where id = v_t.assignment_id;

  select * into v_check from public.ce__check_answer(p_question, coalesce(p_response, '{}'::jsonb));
  v_first := not exists (select 1 from public.ce_attempt_answers where attempt_id = p_attempt and question_id = p_question);

  insert into public.ce_attempt_answers (attempt_id, question_id, response, is_correct, is_first)
  values (p_attempt, p_question, coalesce(p_response, '{}'::jsonb), v_check.is_correct, v_first);

  update public.ce_attempts set
    total_answers  = total_answers + 1,
    total_correct  = total_correct + (v_check.is_correct)::int,
    answered_count = answered_count + (v_first)::int,
    correct_count  = correct_count + (v_first and v_check.is_correct)::int,
    credits        = credits + case when v_check.is_correct and v_a.play_type = 'team' and v_a.mode in ('territory','team_vault') then 1 else 0 end,
    last_answer_at = now()
  where id = p_attempt
  returning * into v_t;

  -- Team scoring for score-based team modes
  if v_check.is_correct and v_a.play_type = 'team' and v_t.team_id is not null and v_a.mode in ('classic','nitro_relay') then
    v_gain := case v_a.mode when 'classic' then 100 else 10 end;
    update public.ce_teams set score = score + v_gain where id = v_t.team_id returning score into v_score;
    insert into public.ce_team_events (assignment_id, team_id, user_id, kind, amount)
    values (v_a.id, v_t.team_id, v_uid, 'answer', v_gain);
  end if;

  v_reveal := coalesce((v_a.settings->>'show_answers')::boolean, true);
  return jsonb_build_object(
    'correct', v_check.is_correct,
    'first', v_first,
    'correct_choices', case when v_reveal then to_jsonb(v_check.correct_choices) else null end,
    'accepted_answers', case when v_reveal then to_jsonb(v_check.accepted_answers) else null end,
    'explanation', case when v_reveal then v_check.explanation else null end,
    'answered_count', v_t.answered_count,
    'correct_count', v_t.correct_count,
    'credits', v_t.credits,
    'team_gain', v_gain);
end;
$$;

-- Writes the gradebook cell from the best submitted attempt (unless the teacher overrode it).
create or replace function public.ce__sync_grade(p_assignment uuid, p_user uuid)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_a     public.ce_assignments;
  v_best  numeric;
  v_late  boolean;
  v_pts   numeric;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  select * into v_a from public.ce_assignments where id = p_assignment;
  if not v_a.is_graded then return null; end if;
  select percent, is_late into v_best, v_late from public.ce_attempts
   where assignment_id = p_assignment and user_id = p_user and status = 'submitted'
   order by percent desc nulls last, submitted_at asc limit 1;
  if v_best is null then return null; end if;
  v_pts := round(v_best / 100.0 * v_a.points_possible, 2);
  insert into public.ce_grades (assignment_id, student_id, points, status)
  values (p_assignment, p_user, v_pts, case when v_late then 'late' else null end)
  on conflict (assignment_id, student_id) do update
    set points = case when public.ce_grades.is_override then public.ce_grades.points else excluded.points end,
        status = case
          when public.ce_grades.status = 'excused' then 'excused'
          when public.ce_grades.is_override then public.ce_grades.status
          else excluded.status end;
  return v_pts;
end;
$$;
revoke execute on function public.ce__sync_grade(uuid, uuid) from public, anon, authenticated;

create or replace function public.ce_submit_attempt(p_attempt uuid, p_game_score bigint default 0)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := (select auth.uid());
  v_t        public.ce_attempts;
  v_a        public.ce_assignments;
  v_total    integer;
  v_percent  numeric;
  v_first    boolean;
  v_coins    integer;
  v_today    integer;
  v_points   numeric;
  v_medals   text[] := '{}';
  v_prof     public.ce_profiles;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  select * into v_t from public.ce_attempts where id = p_attempt for update;
  if not found or v_t.user_id <> v_uid then raise exception 'Attempt not found' using errcode = 'P0002'; end if;
  if v_t.status <> 'in_progress' then raise exception 'Already submitted' using errcode = 'P0001'; end if;
  select * into v_a from public.ce_assignments where id = v_t.assignment_id;

  v_total := greatest(coalesce(array_length(v_t.question_order, 1), 0), 1);
  v_percent := round(v_t.correct_count * 100.0 / v_total, 2);
  v_first := not exists (select 1 from public.ce_attempts where assignment_id = v_a.id and user_id = v_uid and status = 'submitted');

  update public.ce_attempts set
    status = 'submitted', submitted_at = now(), percent = v_percent,
    game_score = greatest(0, least(coalesce(p_game_score, 0), 1000000000000)),
    is_late = v_a.due_at is not null and now() > v_a.due_at
  where id = p_attempt returning * into v_t;

  v_points := public.ce__sync_grade(v_a.id, v_uid);

  -- Coins: generous on first submission, small for practice re-runs, daily cap 400 from assignments.
  v_coins := case when v_first then least(10 + 3 * v_t.correct_count, 120) else least(v_t.total_correct, 25) end;
  select coalesce(sum(delta), 0) into v_today from public.ce_coin_ledger
   where user_id = v_uid and reason = 'assignment' and created_at > now() - interval '24 hours';
  v_coins := greatest(0, least(v_coins, 400 - v_today));
  if v_t.answered_count = 0 then v_coins := 0; end if;
  if v_coins > 0 then
    perform public.ce__add_coins(v_uid, v_coins, 'assignment', v_a.id::text);
    update public.ce_attempts set coins_awarded = v_coins where id = p_attempt;
  end if;

  update public.ce_profiles set
    assignments_done   = assignments_done + (v_first)::int,
    questions_answered = questions_answered + v_t.total_answers,
    questions_correct  = questions_correct + v_t.total_correct,
    xp                 = xp + v_t.total_correct * 10 + 25
  where id = v_uid returning * into v_prof;

  if v_percent >= 100 and public.ce__grant_medal(v_uid, 'medal_perfect') then v_medals := array_append(v_medals, 'medal_perfect'); end if;
  if v_prof.assignments_done >= 10 and public.ce__grant_medal(v_uid, 'medal_scholar') then v_medals := array_append(v_medals, 'medal_scholar'); end if;
  if v_prof.questions_correct >= 100 and public.ce__grant_medal(v_uid, 'medal_sharp') then v_medals := array_append(v_medals, 'medal_sharp'); end if;

  return jsonb_build_object(
    'percent', v_percent, 'points', v_points, 'points_possible', v_a.points_possible,
    'correct', v_t.correct_count, 'total', v_total, 'coins', v_coins,
    'is_late', v_t.is_late, 'medals', to_jsonb(v_medals));
end;
$$;

-- ---------------------------------------------------------------------------
-- Team actions (server-authoritative, spend credits earned by correct answers)
-- ---------------------------------------------------------------------------
create or replace function public.ce_team_open_chest(p_attempt uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := (select auth.uid());
  v_t      public.ce_attempts;
  v_a      public.ce_assignments;
  v_team   public.ce_teams;
  v_target public.ce_teams;
  v_roll   numeric := random();
  v_kind   text;
  v_amount bigint := 0;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  select * into v_t from public.ce_attempts where id = p_attempt for update;
  if not found or v_t.user_id <> v_uid then raise exception 'Attempt not found' using errcode = 'P0002'; end if;
  if v_t.status <> 'in_progress' then raise exception 'Attempt is submitted' using errcode = 'P0001'; end if;
  select * into v_a from public.ce_assignments where id = v_t.assignment_id;
  if v_a.mode <> 'team_vault' or v_t.team_id is null then raise exception 'Not a vault game' using errcode = 'P0001'; end if;
  if v_t.credits < 1 then raise exception 'Answer a question correctly to open a vault' using errcode = 'P0001'; end if;
  update public.ce_attempts set credits = credits - 1 where id = p_attempt;

  select * into v_team from public.ce_teams where id = v_t.team_id for update;
  if v_roll < 0.40 then
    v_kind := 'gold';   v_amount := (array[20,30,40,50,75])[1 + floor(random() * 5)::int];
  elsif v_roll < 0.55 then
    v_kind := 'bonus';  v_amount := least(greatest(v_team.score / 4, 25), 300);
  elsif v_roll < 0.70 then
    select * into v_target from public.ce_teams
     where assignment_id = v_a.id and id <> v_team.id and score > 0
     order by score desc, random() limit 1 for update;
    if found then
      v_kind := 'steal'; v_amount := least(greatest(v_target.score * 15 / 100, 10), v_target.score, 250);
      update public.ce_teams set score = score - v_amount where id = v_target.id;
    else
      v_kind := 'gold';  v_amount := 25;
    end if;
  elsif v_roll < 0.80 then
    v_kind := 'lose';   v_amount := -least(v_team.score / 10, 100);
  elsif v_roll < 0.90 then
    v_kind := 'nothing'; v_amount := 0;
  else
    v_kind := 'small';  v_amount := 10;
  end if;

  update public.ce_teams set score = greatest(0, score + v_amount) where id = v_team.id returning * into v_team;
  insert into public.ce_team_events (assignment_id, team_id, user_id, kind, amount, target_team_id)
  values (v_a.id, v_team.id, v_uid, v_kind, v_amount, v_target.id);
  return jsonb_build_object('kind', v_kind, 'amount', v_amount, 'team_score', v_team.score,
    'target', case when v_target.id is null then null else jsonb_build_object('id', v_target.id, 'name', v_target.name) end,
    'credits', v_t.credits - 1);
end;
$$;

create or replace function public.ce_team_claim_tile(p_attempt uuid, p_tile integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := (select auth.uid());
  v_t      public.ce_attempts;
  v_a      public.ce_assignments;
  v_size   integer;
  v_owner  uuid;
  v_cost   integer;
  v_x      integer;
  v_y      integer;
  v_adj    boolean;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  select * into v_t from public.ce_attempts where id = p_attempt for update;
  if not found or v_t.user_id <> v_uid then raise exception 'Attempt not found' using errcode = 'P0002'; end if;
  if v_t.status <> 'in_progress' then raise exception 'Attempt is submitted' using errcode = 'P0001'; end if;
  select * into v_a from public.ce_assignments where id = v_t.assignment_id;
  if v_a.mode <> 'territory' or v_t.team_id is null then raise exception 'Not a territory game' using errcode = 'P0001'; end if;
  v_size := greatest(6, least(20, coalesce((v_a.settings->>'map_size')::int, 10)));
  if p_tile < 0 or p_tile >= v_size * v_size then raise exception 'Invalid tile' using errcode = 'P0001'; end if;

  perform pg_advisory_xact_lock(hashtext('territory:' || v_a.id::text));
  select team_id into v_owner from public.ce_team_tiles where assignment_id = v_a.id and tile = p_tile;
  if v_owner = v_t.team_id then raise exception 'Your team already owns that tile' using errcode = 'P0001'; end if;
  v_cost := case when v_owner is null then 1 else 2 end;
  if v_t.credits < v_cost then
    raise exception 'You need % claim(s) for that tile — answer more questions!', v_cost using errcode = 'P0001';
  end if;

  -- Must border your team's land (unless your team has none yet)
  v_x := p_tile % v_size; v_y := p_tile / v_size;
  if exists (select 1 from public.ce_team_tiles where assignment_id = v_a.id and team_id = v_t.team_id) then
    select exists (
      select 1 from public.ce_team_tiles
       where assignment_id = v_a.id and team_id = v_t.team_id
         and ((tile = p_tile - 1 and v_x > 0) or (tile = p_tile + 1 and v_x < v_size - 1)
              or tile = p_tile - v_size or tile = p_tile + v_size)
    ) into v_adj;
    if not v_adj then raise exception 'Claim a tile next to your team''s land' using errcode = 'P0001'; end if;
  end if;

  update public.ce_attempts set credits = credits - v_cost where id = p_attempt;
  insert into public.ce_team_tiles (assignment_id, tile, team_id, claimed_by)
  values (v_a.id, p_tile, v_t.team_id, v_uid)
  on conflict (assignment_id, tile) do update set team_id = excluded.team_id, claimed_by = excluded.claimed_by, claimed_at = now();

  update public.ce_teams t set score = (select count(*) from public.ce_team_tiles tt where tt.team_id = t.id)
   where t.assignment_id = v_a.id and (t.id = v_t.team_id or t.id = v_owner);
  insert into public.ce_team_events (assignment_id, team_id, user_id, kind, amount, target_team_id)
  values (v_a.id, v_t.team_id, v_uid, case when v_owner is null then 'claim' else 'capture' end, p_tile, v_owner);
  return jsonb_build_object('tile', p_tile, 'cost', v_cost, 'credits', v_t.credits - v_cost);
end;
$$;

-- ---------------------------------------------------------------------------
-- Live games
-- ---------------------------------------------------------------------------
create or replace function public.ce_create_live_session(
  p_class uuid, p_set uuid, p_mode text, p_title text,
  p_settings jsonb default '{}'::jsonb, p_scheduled_for timestamptz default null,
  p_graded boolean default false, p_category uuid default null, p_points numeric default 100)
returns public.ce_live_sessions
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid    uuid := (select auth.uid());
  v_s      public.ce_live_sessions;
  v_aid    uuid;
  v_name   text;
  v_status text;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_is_class_teacher(p_class) then raise exception 'Not your class' using errcode = '42501'; end if;
  if not public.ce_owns_set(p_set) then raise exception 'Use a set from your library' using errcode = 'P0001'; end if;
  if not public.ce_valid_mode('live', p_mode) then raise exception 'Unknown live mode' using errcode = 'P0001'; end if;
  if (select question_count from public.ce_question_sets where id = p_set) < 1 then
    raise exception 'That set has no questions yet' using errcode = 'P0001';
  end if;
  v_status := case when p_scheduled_for is not null and p_scheduled_for > now() + interval '1 minute' then 'scheduled' else 'lobby' end;
  if v_status = 'lobby' and exists (select 1 from public.ce_live_sessions where class_id = p_class and status in ('lobby','running')) then
    raise exception 'This class already has a live game going. End it first.' using errcode = 'P0001';
  end if;

  insert into public.ce_live_sessions (class_id, host_id, set_id, mode, title, status, settings, scheduled_for)
  values (p_class, v_uid, p_set, p_mode, left(trim(p_title), 100), v_status,
          coalesce(p_settings, '{}'::jsonb), case when v_status = 'scheduled' then p_scheduled_for else null end)
  returning * into v_s;

  if coalesce(p_graded, false) then
    insert into public.ce_assignments (class_id, created_by, set_id, title, play_type, mode, category_id,
                                    points_possible, is_graded, status, live_session_id, open_at)
    values (p_class, v_uid, p_set, left(trim(p_title), 100), 'live', p_mode, p_category,
            coalesce(p_points, 100), true, 'published', v_s.id, v_s.scheduled_for)
    returning id into v_aid;
    update public.ce_live_sessions set assignment_id = v_aid where id = v_s.id returning * into v_s;
  end if;

  select display_name into v_name from public.ce_profiles where id = v_uid;
  insert into public.ce_stream_posts (class_id, author_id, kind, body, live_session_id)
  values (p_class, v_uid, 'live',
          coalesce(v_name, 'Your teacher') ||
          case when v_status = 'scheduled' then ' scheduled a live game: "' else ' started a live game: "' end
          || v_s.title || '"', v_s.id);
  return v_s;
end;
$$;

-- p_results: [{user_id, rank, score, correct, answered, team}]
create or replace function public.ce_finish_live_session(p_session uuid, p_results jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := (select auth.uid());
  v_s       public.ce_live_sessions;
  v_a       public.ce_assignments;
  v_r       jsonb;
  v_user    uuid;
  v_rank    integer;
  v_correct integer;
  v_answered integer;
  v_coins   integer;
  v_prof    public.ce_profiles;
  v_count   integer := 0;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  select * into v_s from public.ce_live_sessions where id = p_session for update;
  if not found or v_s.host_id <> v_uid then raise exception 'Not your live game' using errcode = '42501'; end if;
  if v_s.status not in ('running','lobby') then raise exception 'This live game already ended' using errcode = 'P0001'; end if;
  if jsonb_typeof(p_results) <> 'array' then raise exception 'Results must be an array'; end if;
  if v_s.assignment_id is not null then
    select * into v_a from public.ce_assignments where id = v_s.assignment_id;
  end if;

  if v_s.status = 'lobby' then
    update public.ce_live_sessions set status = 'running' where id = p_session;
  end if;
  update public.ce_live_sessions set status = 'ended' where id = p_session;

  for v_r in select * from jsonb_array_elements(p_results) loop
    begin
      v_user := (v_r->>'user_id')::uuid;
    exception when others then
      continue;
    end;
    continue when not exists (select 1 from public.ce_class_members where class_id = v_s.class_id and user_id = v_user);
    continue when exists (select 1 from public.ce_live_results where session_id = p_session and user_id = v_user);
    v_rank     := greatest(1, coalesce((v_r->>'rank')::int, 999));
    v_answered := greatest(0, least(coalesce((v_r->>'answered')::int, 0), 2000));
    v_correct  := greatest(0, least(coalesce((v_r->>'correct')::int, 0), v_answered));

    v_coins := case when v_answered = 0 then 0
                    else least(100, (case v_rank when 1 then 60 when 2 then 45 when 3 then 35 else 20 end) + least(v_correct, 40)) end;
    insert into public.ce_live_results (session_id, user_id, rank, score, correct, answered, team, coins_awarded)
    values (p_session, v_user, v_rank, greatest(0, least(coalesce((v_r->>'score')::bigint, 0), 1000000000000)),
            v_correct, v_answered, left(v_r->>'team', 40), v_coins);
    if v_coins > 0 then
      perform public.ce__add_coins(v_user, v_coins, 'live_game', p_session::text);
    end if;

    update public.ce_profiles set
      games_played = games_played + (v_answered > 0)::int,
      games_won = games_won + (v_rank = 1 and v_answered > 0)::int,
      questions_answered = questions_answered + v_answered,
      questions_correct = questions_correct + v_correct,
      xp = xp + v_correct * 10 + case when v_answered > 0 then 50 else 0 end
    where id = v_user returning * into v_prof;

    if v_answered > 0 then perform public.ce__grant_medal(v_user, 'medal_first_game'); end if;
    if v_rank = 1 and v_answered > 0 then perform public.ce__grant_medal(v_user, 'medal_first_win'); end if;
    if v_prof.games_won >= 5 then perform public.ce__grant_medal(v_user, 'medal_champion'); end if;
    if v_prof.questions_correct >= 100 then perform public.ce__grant_medal(v_user, 'medal_sharp'); end if;

    if v_a.id is not null and v_a.is_graded then
      insert into public.ce_grades (assignment_id, student_id, points, status)
      values (v_a.id, v_user,
              case when v_answered = 0 then 0 else round(v_correct * 1.0 / v_answered * v_a.points_possible, 2) end,
              case when v_answered = 0 then 'missing' else null end)
      on conflict (assignment_id, student_id) do update
        set points = case when public.ce_grades.is_override then public.ce_grades.points else excluded.points end,
            status = case when public.ce_grades.is_override or public.ce_grades.status = 'excused'
                          then public.ce_grades.status else excluded.status end;
    end if;
    v_count := v_count + 1;
  end loop;

  -- Students in the class who never showed up get a missing grade on graded games
  if v_a.id is not null and v_a.is_graded then
    insert into public.ce_grades (assignment_id, student_id, points, status)
    select v_a.id, m.user_id, 0, 'missing' from public.ce_class_members m
     where m.class_id = v_s.class_id
       and not exists (select 1 from public.ce_live_results r where r.session_id = p_session and r.user_id = m.user_id)
    on conflict (assignment_id, student_id) do nothing;
  end if;

  return jsonb_build_object('recorded', v_count);
end;
$$;

-- ===================== 20261011000600_realtime_storage.sql =====================
-- ============================================================================
-- Cesium — realtime (postgres changes + private broadcast channels) and storage
-- ============================================================================

-- Tables that stream row changes to clients (RLS still applies per subscriber)
do $$
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
end $$;

alter publication supabase_realtime add table
  public.ce_live_sessions,
  public.ce_chat_messages,
  public.ce_stream_posts,
  public.ce_stream_replies,
  public.ce_stream_likes,
  public.ce_teams,
  public.ce_team_tiles,
  public.ce_team_events;

-- ---------------------------------------------------------------------------
-- Private broadcast channels for live games
--   live:<session>:all          host -> everyone in the class
--   live:<session>:p:<user>     host <-> one player (answers, private info)
-- ---------------------------------------------------------------------------
create or replace function public.ce_live_topic_allowed(p_topic text, p_write boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_parts text[] := string_to_array(coalesce(p_topic, ''), ':');
  v_sid   uuid;
  v_user  uuid;
  v_uid   uuid := (select auth.uid());
  v_s     public.ce_live_sessions;
begin
  if v_uid is null or array_length(v_parts, 1) < 3 or v_parts[1] <> 'live' then
    return false;
  end if;
  begin
    v_sid := v_parts[2]::uuid;
  exception when others then
    return false;
  end;
  select * into v_s from public.ce_live_sessions where id = v_sid;
  if not found or v_s.status not in ('lobby','running','ended') then
    return false;
  end if;
  if v_s.status = 'ended' and (p_write and v_s.host_id <> v_uid) then
    return false;
  end if;

  if v_parts[3] = 'all' and array_length(v_parts, 1) = 3 then
    if p_write then
      return v_s.host_id = v_uid;
    end if;
    return v_s.host_id = v_uid
        or exists (select 1 from public.ce_class_members where class_id = v_s.class_id and user_id = v_uid);
  elsif v_parts[3] = 'p' and array_length(v_parts, 1) = 4 then
    begin
      v_user := v_parts[4]::uuid;
    exception when others then
      return false;
    end;
    return v_s.host_id = v_uid
        or (v_user = v_uid and exists (
              select 1 from public.ce_class_members where class_id = v_s.class_id and user_id = v_uid));
  end if;
  return false;
end;
$$;

create policy "cesium live channels: read" on realtime.messages
  for select to authenticated
  using (realtime.messages.extension in ('broadcast','presence')
         and public.ce_live_topic_allowed((select realtime.topic()), false));

create policy "cesium live channels: write" on realtime.messages
  for insert to authenticated
  with check (realtime.messages.extension in ('broadcast','presence')
              and public.ce_live_topic_allowed((select realtime.topic()), true));

-- ---------------------------------------------------------------------------
-- Storage: question images and class banners (public read, owner write)
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('ce-set-images',    'ce-set-images',    true, 5242880, array['image/png','image/jpeg','image/gif','image/webp']),
  ('ce-class-banners', 'ce-class-banners', true, 5242880, array['image/png','image/jpeg','image/gif','image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create policy "cesium images: teachers upload to own folder" on storage.objects
  for insert to authenticated
  with check (bucket_id in ('ce-set-images','ce-class-banners')
              and (storage.foldername(name))[1] = (select auth.uid())::text
              and public.ce_is_teacher());

create policy "cesium images: owners update" on storage.objects
  for update to authenticated
  using (bucket_id in ('ce-set-images','ce-class-banners') and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "cesium images: owners delete" on storage.objects
  for delete to authenticated
  using (bucket_id in ('ce-set-images','ce-class-banners') and (storage.foldername(name))[1] = (select auth.uid())::text);

-- Class banners are an optional custom image URL on the class
alter table public.ce_classes add column banner_url text check (banner_url is null or char_length(banner_url) <= 1000);
grant update (banner_url) on public.ce_classes to authenticated;

