-- ===================== 20261011000800_account.sql =====================
-- ============================================================================
-- Cesium — self-service account deletion
-- ============================================================================
create or replace function public.ce_delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_uid uuid := (select auth.uid());
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if v_uid is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  -- profiles, classes (for teachers), memberships, attempts, grades etc. cascade from auth.users
  delete from public.ce_profiles where id = v_uid;  -- leaves Cesium only; the Cinnabar account and its files stay
end;
$$;
revoke execute on function public.ce_delete_my_account() from public, anon;
grant execute on function public.ce_delete_my_account() to authenticated;

-- ===================== 20261011000900_no_email_verification.sql =====================
-- Cesium does not use email verification: every new account is confirmed the moment it is created,
-- so students and teachers can log in right away even if "Confirm email" is left on in the dashboard.
-- (removed for Cinnabar: Cinnabar's signup.sql confirms accounts)

-- ===================== 20261011001000_admin.sql =====================
-- =============================================================================
-- Admin panel
-- In Cinnabar the first admin is set with SQL (see the top of this file).
-- Admins can also grant admin to other accounts from the panel.
-- =============================================================================

alter table public.ce_profiles add column if not exists is_admin boolean not null default false;
-- (profiles UPDATE is granted per-column to authenticated, so users can never set is_admin themselves.)

create or replace function public.ce_is_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select is_admin from public.ce_profiles where id = (select auth.uid())), false);
$$;
grant execute on function public.ce_is_admin() to authenticated;

create or replace function public.ce__require_admin()
returns void language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if not public.ce_is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
end;
$$;
revoke execute on function public.ce__require_admin() from public, anon, authenticated;

-- (removed for Cinnabar: admin is granted by SQL, never by picking a name)

-- Overview ------------------------------------------------------------------------
create or replace function public.ce_admin_stats()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  return jsonb_build_object(
    'users', (select count(*) from public.ce_profiles),
    'students', (select count(*) from public.ce_profiles where role = 'student'),
    'teachers', (select count(*) from public.ce_profiles where role = 'teacher'),
    'admins', (select count(*) from public.ce_profiles where is_admin),
    'classes', (select count(*) from public.ce_classes where archived_at is null),
    'sets', (select count(*) from public.ce_question_sets),
    'questions', (select count(*) from public.ce_questions),
    'assignments', (select count(*) from public.ce_assignments),
    'attempts', (select count(*) from public.ce_attempts),
    'live_now', (select count(*) from public.ce_live_sessions where status in ('lobby', 'running')),
    'live_total', (select count(*) from public.ce_live_sessions),
    'messages', (select count(*) from public.ce_chat_messages),
    'open_reports', (select count(*) from public.ce_reports where status = 'open'),
    'coins', (select coalesce(sum(coins), 0) from public.ce_profiles)
  );
end;
$$;

-- Users ---------------------------------------------------------------------------
create or replace function public.ce_admin_list_users(p_search text default '', p_limit integer default 100)
returns table (
  id uuid, display_name text, email text, role text, is_admin boolean, coins integer,
  classes integer, created_at timestamptz, last_sign_in_at timestamptz
)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  return query
    select p.id, p.display_name, u.email::text, p.role, p.is_admin, p.coins,
           ((select count(*) from public.ce_class_members m where m.user_id = p.id)
             + (select count(*) from public.ce_classes c where c.teacher_id = p.id))::integer,
           p.created_at, u.last_sign_in_at
      from public.ce_profiles p
      join auth.users u on u.id = p.id
     where coalesce(p_search, '') = ''
        or p.display_name ilike '%' || p_search || '%'
        or u.email ilike '%' || p_search || '%'
     order by p.created_at desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

create or replace function public.ce_admin_set_role(p_user uuid, p_role text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if p_role not in ('student', 'teacher') then
    raise exception 'Role must be student or teacher' using errcode = 'P0001';
  end if;
  update public.ce_profiles set role = p_role where id = p_user;
  if not found then raise exception 'User not found' using errcode = 'P0001'; end if;
end;
$$;

create or replace function public.ce_admin_set_admin(p_user uuid, p_value boolean)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if not p_value and p_user = (select auth.uid()) then
    raise exception 'You can''t remove your own admin access' using errcode = 'P0001';
  end if;
  update public.ce_profiles set is_admin = p_value where id = p_user;
  if not found then raise exception 'User not found' using errcode = 'P0001'; end if;
end;
$$;

create or replace function public.ce_admin_grant_coins(p_user uuid, p_amount integer)
returns integer language plpgsql security definer set search_path = '' as $$
declare v_now integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if p_amount is null or p_amount = 0 or abs(p_amount) > 1000000 then
    raise exception 'Enter an amount between -1,000,000 and 1,000,000' using errcode = 'P0001';
  end if;
  select coins into v_now from public.ce_profiles where id = p_user;
  if v_now is null then raise exception 'User not found' using errcode = 'P0001'; end if;
  -- never take a balance below zero
  return public.ce__add_coins(p_user, greatest(p_amount, -v_now), 'admin_grant');
end;
$$;

create or replace function public.ce_admin_grant_all_items(p_user uuid)
returns integer language plpgsql security definer set search_path = '' as $$
declare v_count integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  insert into public.ce_inventory (user_id, item_id)
  select p_user, i.id from public.ce_items i
  on conflict do nothing;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

create or replace function public.ce_admin_reset_daily(p_user uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  update public.ce_profiles set last_daily_claim = null where id = p_user;
end;
$$;

create or replace function public.ce_admin_delete_user(p_user uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if p_user = (select auth.uid()) then
    raise exception 'Use Settings to delete your own account' using errcode = 'P0001';
  end if;
  delete from public.ce_profiles where id = p_user;  -- removes them from Cesium, not from Cinnabar
end;
$$;

