-- Classes -------------------------------------------------------------------------
create or replace function public.ce_admin_list_classes()
returns table (
  id uuid, name text, period text, code text, color text, teacher_id uuid, teacher_name text,
  students integer, assignments integer, archived boolean, created_at timestamptz, i_am_member boolean
)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  return query
    select c.id, c.name, c.period::text, c.code, c.color, c.teacher_id, t.display_name,
           (select count(*) from public.ce_class_members m where m.class_id = c.id)::integer,
           (select count(*) from public.ce_assignments a where a.class_id = c.id)::integer,
           c.archived_at is not null, c.created_at,
           exists (select 1 from public.ce_class_members m where m.class_id = c.id and m.user_id = (select auth.uid()))
      from public.ce_classes c
      join public.ce_profiles t on t.id = c.teacher_id
     order by c.created_at desc;
end;
$$;

create or replace function public.ce_admin_join_class(p_class uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if exists (select 1 from public.ce_classes where id = p_class and teacher_id = (select auth.uid())) then
    raise exception 'You teach this class' using errcode = 'P0001';
  end if;
  insert into public.ce_class_members (class_id, user_id) values (p_class, (select auth.uid())) on conflict do nothing;
end;
$$;

create or replace function public.ce_admin_leave_class(p_class uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  delete from public.ce_class_members where class_id = p_class and user_id = (select auth.uid());
end;
$$;

create or replace function public.ce_admin_end_live_sessions()
returns integer language plpgsql security definer set search_path = '' as $$
declare v_count integer;
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  -- "cancelled" is a legal move from every open state; no results are saved for these.
  update public.ce_live_sessions set status = 'cancelled'
   where status in ('lobby', 'running', 'scheduled');
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- Site settings -------------------------------------------------------------------
create or replace function public.ce_admin_get_settings()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  return jsonb_build_object(
    'teacher_signup_code', coalesce((select value from public.ce_app_config where key = 'teacher_signup_code'), ''),
    'blocked_words', coalesce((select jsonb_agg(word order by word) from public.ce_blocked_words), '[]'::jsonb)
  );
end;
$$;

create or replace function public.ce_admin_set_teacher_code(p_code text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if coalesce(trim(p_code), '') = '' then
    delete from public.ce_app_config where key = 'teacher_signup_code';
  else
    insert into public.ce_app_config (key, value) values ('teacher_signup_code', trim(p_code))
    on conflict (key) do update set value = excluded.value;
  end if;
end;
$$;

create or replace function public.ce_admin_set_blocked_word(p_word text, p_blocked boolean)
returns void language plpgsql security definer set search_path = '' as $$
declare v_word text := lower(trim(p_word));
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if char_length(v_word) not between 2 and 40 then
    raise exception 'Words must be 2 to 40 characters' using errcode = 'P0001';
  end if;
  if p_blocked then
    insert into public.ce_blocked_words (word) values (v_word) on conflict do nothing;
  else
    delete from public.ce_blocked_words where word = v_word;
  end if;
end;
$$;

-- Execute grants: these all check is_admin() themselves.
do $$
declare f text;
begin
  foreach f in array array[
    'ce_admin_stats()', 'ce_admin_list_users(text, integer)', 'ce_admin_set_role(uuid, text)', 'ce_admin_set_admin(uuid, boolean)',
    'ce_admin_grant_coins(uuid, integer)', 'ce_admin_grant_all_items(uuid)', 'ce_admin_reset_daily(uuid)', 'ce_admin_delete_user(uuid)', 'ce_admin_list_classes()',
    'ce_admin_join_class(uuid)', 'ce_admin_leave_class(uuid)', 'ce_admin_end_live_sessions()', 'ce_admin_get_settings()', 'ce_admin_set_teacher_code(text)', 'ce_admin_set_blocked_word(text, boolean)'
  ] loop
    execute format('revoke execute on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end;
$$;

-- ===================== 20261011001100_retire_ffa.sql =====================
-- FFA Fight has been removed. New games can't use it; any open FFA lobbies are cancelled.
create or replace function public.ce_valid_mode(p_play_type text, p_mode text)
returns boolean language sql immutable as $$
  select case p_play_type
    when 'solo' then p_mode in ('classic','vault','nitro','tycoon','speedrun')
    when 'team' then p_mode in ('classic','nitro_relay','territory','team_vault')
    when 'live' then p_mode in ('stock_rush','head2head','vault','nitro','tug_of_war','tycoon','territory')
    else false end;
$$;

update public.ce_live_sessions set status = 'cancelled'
 where mode = 'ffa_fight' and status in ('scheduled', 'lobby', 'running');

