-- ===================== 20261011001300_teachers_create_only.sql =====================
-- Teachers never join classes; they only create them. This also applies to the admin
-- "join any class" tool: switch your own view to student first.
create or replace function public.ce_admin_join_class(p_class uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  perform public.ce__require_admin();
  if public.ce_is_teacher() then
    raise exception 'Teachers can''t join classes. Switch to the student view first.' using errcode = 'P0001';
  end if;
  insert into public.ce_class_members (class_id, user_id) values (p_class, (select auth.uid())) on conflict do nothing;
end;
$$;

-- ===================== Cinnabar: edu accounts only =====================
-- profiles.edu comes from the "school account" box at sign-up (db/schema.sql). It is self-declared.
create or replace function public.ce_is_edu() returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select edu from public.profiles where id = (select auth.uid())), false) $$;
grant execute on function public.ce_is_edu() to authenticated;

-- every Cesium table: nothing at all unless the caller is an edu account (restrictive = ANDed with Cesium's own policies)
do $$ declare t text; begin
  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relkind = 'r' and c.relname like 'ce\_%' loop
    execute format('drop policy if exists "cinnabar: edu accounts only" on public.%I', t);
    execute format('create policy "cinnabar: edu accounts only" on public.%I as restrictive for all to public using (public.ce_is_edu()) with check (public.ce_is_edu())', t);
  end loop;
end $$;

-- the Cesium profile is made here (it used to be a trigger on auth.users in Cesium's own project)
create or replace function public.ce_enroll(p_role text, p_name text default null, p_teacher_code text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  v_role text := coalesce(p_role, 'student');
  v_name text := trim(coalesce(p_name, ''));
  v_code text;
begin
  if v_uid is null then raise exception 'Sign in first' using errcode = '28000'; end if;
  if not public.ce_is_edu() then raise exception 'Cesium is for education accounts' using errcode = '42501'; end if;
  if exists (select 1 from public.ce_profiles where id = v_uid) then return; end if;
  if v_role not in ('student', 'teacher') then v_role := 'student'; end if;
  if v_role = 'teacher' then
    select value into v_code from public.ce_app_config where key = 'teacher_signup_code';
    if v_code is not null and v_code <> '' and coalesce(p_teacher_code, '') <> v_code then
      raise exception 'Invalid teacher access code' using errcode = 'P0001';
    end if;
  end if;
  if v_name = '' then select coalesce(nullif(display_name, ''), split_part(email, '@', 1), 'Cesium user') into v_name from public.profiles where id = v_uid; end if;
  v_name := left(coalesce(v_name, 'Cesium user'), 40);
  if public.ce_has_blocked_word(v_name) then v_name := public.ce_clean_text(v_name); end if;
  insert into public.ce_profiles (id, role, display_name, coins) values (v_uid, v_role, v_name, case when v_role = 'student' then 100 else 0 end);
  if v_role = 'student' then
    insert into public.ce_coin_ledger (user_id, delta, reason) values (v_uid, 100, 'welcome_bonus');
    perform public.ce__grant_item(v_uid, 'bg_lab');
    perform public.ce__grant_item(v_uid, 'head_cap');
  else
    perform public.ce__grant_medal(v_uid, 'medal_educator');
  end if;
end $$;
revoke execute on function public.ce_enroll(text, text, text) from public, anon;
grant execute on function public.ce_enroll(text, text, text) to authenticated;

commit;
